window.TXB=window.TXB||{};TXB["alab/Num"]={"1:1":"في اليوم الأول من الشهر الثاني (أي شهر نيسان ; أبريل) من السنة الثانية لخروج بني إسرائيل من ديار مصر، أمر الرب موسى في برية سيناء في خيمة الاجتماع قائلا:","1:2":"«أحصوا كل ذكر باسمه من شعب إسرائيل حسب قبائلهم وبيوت آبائهم.","1:3":"وعليك أنت وهرون أن تحسبهم وفقا لفرقهم من ابن عشرين سنة فما فوق، من القادرين على القتال في الحرب، من إسرائيل.","1:4":"وليكن معكما من كل سبط رجل يتولى رياسة بيت آبائه.","1:5":"وهذه أسماء الرجال الذين يشرفون معكما على الإحصاء: عن سبط رأوبين أليصور بن شديئور.","1:6":"عن سبط شمعون شلوميئيل بن صوريشداي.","1:7":"عن سبط يهوذا نحشون بن عميناداب.","1:8":"عن سبط يساكر نثنائيل بن صوغر.","1:9":"عن سبط زبولون أليآب بن حيلون.","1:10":"عن سبط أفرايم بن يوسف أليشمع بن عميهود. عن سبط منسى بن يوسف جمليئيل بن فدهصور.","1:11":"عن سبط بنيامين أبيدن بن جدعوني.","1:12":"عن سبط دان أخيعزر بن عميشداي.","1:13":"عن سبط أشير فجعيئيل بن عكرن.","1:14":"عن سبط جاد ألياساف بن دعوئيل.","1:15":"عن سبط نفتالي أخيرع بن عينن.","1:16":"هؤلاء هم الرجال المنتخبون من بين الشعب، رؤساء أسباطهم وشيوخ عشائرهم»","1:17":"فأخذ موسى وهرون هؤلاء الرجال الذين تعينوا بأسمائهم،","1:18":"وجمعا كل الشعب في أول الشهر الثاني. فانتسب كل ذكر باسمه من ابن عشرين فما فوق إلى سبطه حسب عشيرته،","1:19":"كما أمر الرب موسى. فأحصاهم في صحراء سيناء.","1:20":"فمن نسل رأوبين بكر إسرائيل تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:21":"فكان عدد المحصين من سبط رأوبين ستة وأربعين ألفا وخمس مئة.","1:22":"ومن نسل شمعون، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:23":"فكان عدد المحصين من سبط شمعون تسعة وخمسين ألفا وثلاث مئة.","1:24":"ومن نسل جاد، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:25":"فكان عدد المحصين من سبط جاد خمسة وأربعين ألفا وست مئة وخمسين.","1:26":"ومن نسل يهوذا، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:27":"فكان عدد المحصين من سبط يهوذا أربعة وسبعين ألفا وست مئة.","1:28":"ومن نسل يساكر، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:29":"فكان عدد المحصين من سبط يساكر أربعة وخمسين ألفا وأربع مئة.","1:30":"ومن نسل زبولون، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:31":"فكان عدد المحصين من سبط زبولون سبعة وخمسين ألفا وأربع مئة.","1:32":"ومن نسل أفرايم بن يوسف، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:33":"فكان عدد المحصين من سبط أفرايم أربعين ألفا وخمس مئة.","1:34":"ومن نسل منسى بن يوسف، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:35":"فكان عدد المحصين من سبط منسى اثنين وثلاثين ألفا ومئتين.","1:36":"ومن نسل بنيامين، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:37":"فكان عدد المحصين من سبط بنيامين خمسة وثلاثين ألفا وأربع مئة.","1:38":"ومن نسل دان، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:39":"فكان عدد المحصين من سبط دان اثنين وستين ألفا وسبع مئة","1:40":"ومن نسل أشير، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:41":"فكان عدد المحصين من سبط أشير واحدا وأربعين ألفا وخمس مئة.","1:42":"ومن نسل نفتالي، تم إحصاء جميع الرجال البالغين من العمر عشرين سنة فما فوق، من القادرين على القتال في الحرب، كل باسمه، حسب عشائرهم وبيوت آبائهم،","1:43":"فكان عدد المحصين من سبط نفتالي ثلاثة وخمسين ألفا وأربع مئة.","1:44":"هؤلاء هم جملة الذين أحصاهم موسى وهرون ورؤساء إسرائيل الاثنا عشر الممثلون لأسباطهم.","1:45":"فكان المجموع الكلي للرجال المحصين من إسرائيل البالغين من العمر عشرين سنة فما فوق، حسب بيوت آبائهم من القادرين على القتال في الحرب في إسرائيل","1:46":"ست مئة ألف وثلاثة آلاف وخمس مئة وخمسين.","1:47":"أما اللاويون المنتسبون لسبط آبائهم فلم يحصوا بينهم،","1:48":"إذ قال الرب لموسى:","1:49":"«أما سبط لاوي فلا تحسبه ولا تحصه بين بني إسرائيل،","1:50":"بل اعهد بمسكن الشهادة وأمتعته كلها وسائر ماله إلى اللاويين. فهم ينقلون المسكن وأمتعته كلها ويعتنون به، وحوله يقيمون.","1:51":"وهم الذين يقوضون المسكن عند ارتحاله وينصبونه عند حلوله، وأي واحد آخر غيرهم يقترب منه يقتل.","1:52":"وليضرب بنو إسرائيل خيامهم كل في موضعه في المخيم، وكل تحت راية قومه.","1:53":"وأما اللاويون فيقيمون حول مسكن الشهادة، لئلا يحل سخط الرب على شعب إسرائيل. وليحافظ اللاويون على خدمة مسكن الشهادة وشعائره».","1:54":"فنفذ بنو إسرائيل تماما كل ما أمر الرب به موسى.","2:1":"وخاطب الرب موسى وهرون:","2:2":"«ليخيم بنو إسرائيل كل عند رايته تحت أعلام بيوت آبائهم، وليقيموا مقابل خيمة الاجتماع وحولها. رايته تحت أعلام بيوت آبائهم، وليقيموا مقابل خيمة الاجتماع وحولها.","2:3":"وليخيم سبط يهوذا برايته إلى الشرق حسب عشائره ويكون رئيس سبط يهوذا نحشون بن عميناداب،","2:4":"وعدد جنوده المحصون أربعة وسبعون ألفا وست مئة.","2:5":"ولينزل معه كل من سبط يساكر الذي يرأسه نثنائيل بن صوغر،","2:6":"مع جنده الذين أحصاهم البالغين أربعة وخمسين ألفا وأربع مئة.","2:7":"وسبط زبولون الذي يرأسه أليآب بن حيلون،","2:8":"مع جنده الذين أحصاهم البالغين سبعة وخمسين ألفا وأربع مئة.","2:9":"فمجموع المحصين المقيمين في منطقة يهوذا مئة ألف وستة وثمانون ألفا وأربع مئة من الجنود. هؤلاء يرتحلون أولا.","2:10":"وليخيم رأوبين برايته إلى الجنوب. ويكون رئيس سبط رأوبين أليصور بن شديئور،","2:11":"مع جنده الذين أحصاهم البالغين ستة وأربعين ألفا وخمس مئة.","2:12":"ولينزل معه كل من سبط شمعون الذي يرأسه شلوميئيل بن صوريشداي،","2:13":"مع جنده الذين أحصاهم البالغين تسعة وخمسين ألفا وثلاث مئة.","2:14":"وسبط جاد الذي يرأسه ألياساف بن دعوئيل،","2:15":"مع جنده الذين أحصاهم البالغين خمسة وأربعين ألفا وست مئة وخمسين.","2:16":"فيكون مجموع المحصين المقيمين في منطقة رأوبين مئة ألف وواحدا وخمسين ألفا وأربع مئة وخمسين من الجنود. هؤلاء يرتحلون ثانية.","2:17":"ثم ترتحل خيمة الاجتماع وسبط اللاويين في وسط المخيم. كما ينزلون كذلك يرتحلون. كل ينزل في موضعه مع راياته.","2:18":"وليخيم أفرايم برايته وفرق جنوده إلى الغرب. ويكون رئيس سبط أفرايم أليشمع بن عميهود،","2:19":"وعدد جنده الذين أحصاهم أربعون ألفا وخمس مئة.","2:20":"ولينزل معه كل من سبط منسى الذي يرأسه جمليئيل بن فدهصور،","2:21":"مع جنده الذين أحصاهم البالغين اثنين وثلاثين ألفا ومئتين.","2:22":"وسبط بنيامين الذي يرأسه أبيدن بن جدعوني،","2:23":"مع جنده الذين أحصاهم البالغين خمسة وثلاثين ألفا وأربع مئة.","2:24":"فيكون مجموع المحصين المقيمين في منطقة أفرايم مئة ألف وثمانية آلاف ومئة من الجنود. هؤلاء يرتحلون ثالثة.","2:25":"وليخيم دان برايته وفرق جنوده إلى الشمال. ويكون رئيس سبط دان أخيعزر بن عميشداي،","2:26":"وعدد جنده الذين أحصاهم اثنان وستون ألفا وسبع مئة.","2:27":"ولينزل معه كل من سبط أشير الذي يرأسه فجعيئيل بن عكرن،","2:28":"مع جنده الذين أحصاهم البالغين واحدا وأربعين ألفا وخمس مئة.","2:29":"وسبط نفتالي الذي يرأسه أخيرع بن عينن،","2:30":"مع جنده الذين أحصاهم البالغين ثلاثة وخمسين ألفا وأربع مئة.","2:31":"فيكون مجموع المحصين المقيمين في منطقة دان مئة ألف وسبعة وخمسين ألفا وست مئة. هؤلاء يرتحلون أخيرا براياتهم».","2:32":"فيكون عدد المحصين من بني إسرائيل حسب بيوت آبائهم المقيمين في المخيم وفقا لعشائرهم ست مئة ألف وثلاثة آلاف وخمس مئة وخمسين.","2:33":"أما اللاويون فلم يتم إحصاؤهم بين بني إسرائيل، كما أمر الرب موسى.","2:34":"فنفذ بنو إسرائيل تماما كل ما أمر الرب به موسى في حلهم وترحالهم نازلين تحت راياتهم، كل حسب عشائره وسبطه.","3:1":"وهذه هي مواليد هرون وموسى يوم خاطب الرب موسى في جبل سيناء:","3:2":"هذه هي أسماء أبناء هرون: ناداب البكر، وأبيهو، وألعازار، وإيثامار،","3:3":"الذين كانوا كهنة ممسوحين تكرسوا للكهنوت.","3:4":"إلا أن ناداب وأبيهو ماتا بين يدي الرب عندما قربا نارا غريبة أمامه في صحراء سيناء، ولم يعقبا بنين. وأما ألعازار وإيثامار فقد قاما بخدمة الكهنوت تحت رعاية أبيهما هرون.","3:5":"وقال الرب لموسى:","3:6":"«أحضر سبط لاوي ليمثلوا أمام هرون الكاهن ويخدموه.","3:7":"فيحافظون على شعائره وشعائر كل الشعب أمام خيمة الاجتماع، ويقومون بخدمة المسكن،","3:8":"ويحرسون كل أمتعة خيمة الاجتماع، وينوبون عن الشعب في تأدية واجبات خدمة المسكن.","3:9":"وليكن اللاويون تحت إمرة هرون وأبنائه هبة له من بني إسرائيل.","3:10":"أما هرون وأبناؤه فهم وحدهم يقومون بخدمة الكهنوت، وأي واحد سواهم يقترب من المقدس يقتل».","3:11":"وقال الرب لموسى:","3:12":"«ها إني قد أفرزت اللاويين من بين بني إسرائيل بدلا من أبكار الشعب، فيكون اللاويون خاصتي،","3:13":"لأن كل بكر من شعب إسرائيل هو لي. فقد أفرزت لي كل بكر في إسرائيل من الناس والبهائم منذ أن أهلكت كل بكر في ديار مصر. لي يكونون. أنا الرب».","3:14":"وقال الرب لموسى في صحراء سيناء:","3:15":"«أحص كل ذكر من أبناء سبط لاوي من ابن شهر فما فوق، حسب بيوت آبائهم وعشائرهم».","3:16":"فأحصاهم موسى وفقا لأمر الرب.","3:17":"وهذه هي أسماء أبناء لاوي: جرشون وقهات ومراري.","3:18":"أما اسما ابني جرشون حسب عشائرهما، فهما: لبني وشمعي","3:19":"وبنو قهات حسب عشائرهم هم: عمرام ويصهار وحبرون وعزيئيل.","3:20":"وابنا مراري حسب عشائرهما هما محلي وموشي. هذه هي عشائر اللاويين وفقا لبيوت آبائهم.","3:21":"فقد تفرع عن جرشون عشيرتا اللبنيين والشمعيين. هاتان هما عشيرتا الجرشونيين.","3:22":"وكان عدد الذكور المحصين منهما من ابن شهر وما فوق، سبعة آلاف وخمس مئة.","3:23":"وقد خيمت عشيرتا الجرشونيين وراء المسكن إلى الغرب،","3:24":"وكان رئيسهما ألياساف بن لابل","3:25":"وعهد إلى الجرشونيين بحراسة المسكن في خيمة الاجتماع والخيمة وغطائها وستائر باب خيمة الاجتماع،","3:26":"وستائر الدار وستارة باب الدار التي حول المسكن وحول جوانب المذبح وحباله مع كل خدمته.","3:27":"وتفرع عن قهات عشائر العمراميين واليصهاريين والحبرونيين والعزيئيليين. هذه هي عشائر القهاتيين.","3:28":"فكان عدد الذكور المحصين منهم من ابن شهر فما فوق، ثمانية آلاف وست مئة. ومهمتهم حراسة القدس.","3:29":"وتخيم عشائر بني قهات في جنوبي المسكن،","3:30":"وكان رئيسها أليصافان بن عزيئيل.","3:31":"وهم يتولون حراسة التابوت والمائدة والمنارة والمذبحين وأمتعة القدس التي يخدمون بها، والحجاب وكل ما يتعلق به.","3:32":"أما رئيس رؤساء اللاويين ألعازار بن هرون الكاهن فيتولى أيضا أمر حراس حراسة القدس.","3:33":"وتفرع عن مراري عشيرتا المحليين والموشيين. هاتان هما عشيرتا مراري.","3:34":"فكان عدد الذكور المحصين منهما من ابن شهر فما فوق، ستة آلاف ومئتين،","3:35":"ورئيسهما صوريئيل بن أبيحايل. وتخيمان إلى شمالي المسكن.","3:36":"ومهمة أبناء مراري حراسة ألواح المسكن وعوارضه وقواعدها وكل أوانيه والعناية بها،","3:37":"وأعمدة جوانب الدار وقواعدها وأوتادها وحبالها.","3:38":"أما موسى وهرون وأبناؤه فينزلون قدام المسكن إلى الشرق ليقوموا بحراسة المقدس نيابة عن بني إسرائيل، وأي واحد سواهم يقترب منه يقتل.","3:39":"فكان مجموع المحصين من ذكور اللاويين من ابن شهر فما فوق، الذين أحصاهم موسى وهرون حسب عشائرهم كما أمر الرب، اثنين وعشرين ألفا.","3:40":"وقال الرب لموسى: «أحص كل بكر ذكر من بني إسرائيل من ابن شهر فما فوق، ودون أسماءهم جميعا،","3:41":"فتفرز لي اللاويين، أنا الرب، ليكونوا لي بدل كل بكر في بني إسرائيل، وكذلك بهائم اللاويين بدل كل بكر في بهائم بني إسرائيل».","3:42":"فأحصى موسى أبكار بني إسرائيل كما أمره الرب،","3:43":"فكان مجموع عدد الذكور الأبكار المحصين، كل باسمه، من ابن شهر فما فوق، اثنين وعشرين ألفا ومئتين وثلاثة وسبعين.","3:44":"وقال الرب لموسى:","3:45":"«أفرز اللاويين بدل كل بكر في بني إسرائيل، وكذلك بهائم اللاويين بدل بهائمهم، فيكون اللاويون خاصتي. أنا الرب.","3:46":"وأما فداء المئتين والثلاثة والسبعين من أبكار بني إسرائيل الزائدين عن عدد اللاويين،","3:47":"فتأخذ عن كل واحد منهم خمسة شواقل (نحو ستين جراما) من الفضة وفقا للوزن المعتمد في القدس فيكون كل عشرين جيرة معادلة لشاقل (أي لاثني عشر جراما).","3:48":"وتعطي الفضة لهرون وأبنائه فدية عن الأبكار الزائدين عن عدد اللاويين»","3:49":"فجمع موسى فضة الفدية من الزائدين عن عدد اللاويين فداء لهم.","3:50":"جباها من أبكار بني إسرائيل، فكانت ألفا وثلاث مئة وخمسة وستين من الفضة على شاقل القدس (نحو ستة عشر كيلو جراما وثلث).","3:51":"وأعطى موسى فضة الفدية لهرون وأبنائه كما أمر الرب.","4:1":"وقال الرب لموسى وهرون:","4:2":"«أحصيا بني قهات من بين أبناء لاوي حسب عشائرهم وبيوت آبائهم،","4:3":"من ابن ثلاثين سنة حتى ابن خمسين، من المتجندين لخدمة خيمة الاجتماع.","4:4":"وهذه هي الخدمة التي توكل إلى بني قهات في خيمة الاجتماع: قدس الأقداس.","4:5":"عند وقت الرحيل، يأتي هرون وأبناؤه وينزلون الحجاب الفاصل، ويغطون به تابوت الشهادة،","4:6":"ويضعون فوقه غطاء من جلد الدلفين، ويبسطون فوقه ثوبا من قماش أزرق ثم يضعون عصيه في حلقاتها.","4:7":"ويبسطون على مائدة خبز الوجوه ثوبا من قماش أزرق ويضعون عليه الصحاف والصحون والأقداح وكاسات الخمر، ويكون الخبز الدائم موجودا عليه،","4:8":"ثم يغطونها بثوب أحمر اللون ويضعون فوقها غطاء من جلد الدلفين ويدخلون عصيها في حلقاتها.","4:9":"ويغطون أيضا المنارة وسرجها وملاقطها ومنافضها، وسائر آنية زيتها التي يستعملونها، بثوب أزرق.","4:10":"ويلفونها مع جميع أوانيها بغطاء من جلد الدلفين، ويضعونها على حمالة.","4:11":"ويبسطون على مذبح الذهب ثوبا أزرق ويغطونه بغطاء من جلد الدلفين، ويدخلون عصيه في حلقاته.","4:12":"وكذلك يلفون جميع أواني الخدمة التي يستعملونها في القدس بثوب أزرق ويغطونها بغطاء من الدلفين ويضعونها على حمالة","4:13":"ويرفعون رماد المذبح ويبسطون عليه ثوبا من قماش بنفسجي،","4:14":"ويضعون عليه جميع أوانيه التي يستعملونها، المجامر والمناشل والرفوش والمناضح، كل أواني المذبح، ويغطونه بغطاء من جلد الدلفين، ثم يدخلون عصيه في حلقاته.","4:15":"وحالما ينتهي هرون وأبناؤه من تغطية القدس وجميع آنيته عند وقت ارتحال المخيم، يقبل بنو قهات ليحملوها. ولكن إياهم أن يمسوا الأشياء المقدسة لئلا يموتوا. هذه هي مسئولية بني قهات في حمل خيمة الاجتماع.","4:16":"ويكون ألعازار بن هرون الكاهن مسئولا عن زيت الإنارة، وعن البخور العطر، وتقدمة الدقيق اليومية ودهن المسحة وعن سائر المسكن وما فيه من القدس وأوانيه».","4:17":"وقال الرب لموسى وهرون:","4:18":"«احرصا ألا ينقرض فرع عشائر القهاتيين من بين اللاويين،","4:19":"بل اعملا هذا الترتيب فيعيشوا ولا يموتوا عند اقترابهم إلى قدس الأقداس. يدخل معهم هرون وأبناؤه ويعينون لكل إنسان خدمته وحمله.","4:20":"ولكن إياهم أن يدخلوا لمشاهدة القدس ولو للحظة، لئلا يهلكوا».","4:21":"وقال الرب لموسى:","4:22":"«أحص جملة بني جرشون أيضا حسب بيوت آبائهم وعشائرهم،","4:23":"من ابن ثلاثين سنة فما فوق حتى ابن خمسين من المتجندين في خدمة خيمة الاجتماع.","4:24":"وهذه هي الخدمات التي توكل إلى عشائر الجرشونيين من عمل وحمل:","4:25":"يحملون شقق المسكن وخيمة الاجتماع وغطاءها وغطاء جلد الدلفين الذي فوقها، وستار مدخل خيمة الاجتماع.","4:26":"وأستار الساحة المحيطة بالمسكن والمذبح، وستارة المدخل والحبال والأواني المستخدمة في خدمتها. ويؤدي الجرشونيون جميع الخدمات الواجبة لها.","4:27":"ويجب أن يقوموا بخدمتهم، سواء أكانت خدمة نقل أم أي عمل آخر، تحت إشراف هرون وأبنائه. وعليك أن تعين لهم ما يتوجب عليهم حمله.","4:28":"هذه هي مسئولية عشائر الجرشونيين في خيمة الاجتماع، ويكون إيثامار بن هرون الكاهن هو المشرف على تأدية واجباتهم.","4:29":"وتحصي بني مراري حسب عشائرهم وبيوت آبائهم،","4:30":"من ابن ثلاثين سنة فما فوق حتى ابن خمسين، من المتجندين في خدمة خيمة الاجتماع.","4:31":"وتكون مسئولية خدمتهم في خيمة الاجتماع نقل ألواح المسكن وعوارضه وأعمدته وقواعده،","4:32":"وأعمدة الساحة المحيطة وقواعدها وأوتادها وحبالها وأوانيها وكل ما يتصل بخدمتها. وحددوا بالتفصيل ما يتوجب على كل رجل حمله.","4:33":"هذه هي مسئولية عشائر المراريين التي يقومون بها في خدمة خيمة الاجتماع تحت إشراف إيثامار بن هرون الكاهن».","4:34":"فأحصى موسى وهرون ورؤساء الشعب جملة أبناء القهاتيين حسب عشائرهم وبيوت آبائهم،","4:35":"من ابن ثلاثين سنة فما فوق إلى ابن خمسين سنة، من المتجندين في خدمة خيمة الاجتماع.","4:36":"فكانت جملة المحصين منهم حسب عشائرهم ألفين وسبع مئة وخمسين.","4:37":"هؤلاء هم المحصون من عشائر القهاتيين الخادمين في خيمة الاجتماع الذين أحصاهم موسى وهرون كما أمر موسى.","4:38":"وتم إحصاء جملة أبناء جرشون حسب عشائرهم وبيوت آبائهم،","4:39":"من ابن ثلاثين سنة فما فوق إلى ابن خمسين سنة، من المتجندين في خدمة خيمة الاجتماع.","4:40":"وكانت جملة المحصين منهم حسب عشائرهم وبيوت آبائهم ألفين وست مئة وثلاثين.","4:41":"هؤلاء هم المحصون من عشائر بني جرشون الخادمين في خيمة الاجتماع الذين أحصاهم موسى وهرون كما أمر الرب.","4:42":"وتم إحصاء جملة بني مراري حسب عشائرهم وبيوت آبائهم،","4:43":"من ابن ثلاثين سنة فما فوق إلى ابن خمسين سنة، من المتجندين في خدمة خيمة الاجتماع.","4:44":"فكانت جملة المحصين منهم حسب عشائرهم ثلاثة آلاف ومئتين.","4:45":"هؤلاء هم المحصون من عشائر بني مراري الذين أحصاهم موسى وهرون حسب أمر الرب على لسان موسى.","4:46":"فكان مجموع المحصين من اللاويين الذين أحصاهم موسى وهرون ورؤساء إسرائيل حسب عشائرهم وبيوت آبائهم.","4:47":"من ابن ثلاثين سنة فما فوق إلى ابن خمسين سنة، المجندين في عمل الخدمة في خيمة الاجتماع وفي خدمة نقلها،","4:48":"ثمانية آلاف وخمس مئة وثمانين.","4:49":"وكما أمر الرب موسى تم تعيين كل لاوي على خدمته وتحديد ما يتوجب عليه حمله. وهكذا تم إحصاؤهم كما أمر الرب موسى.","5:1":"وقال الرب لموسى:","5:2":"«أوص بني إسرائيل أن يعزلوا من المخيم كل أبرص، وكل مريض بالسيلان، وكل من يتنجس بلمس ميت.","5:3":"اعزلوهم إلى خارج المخيم سواء كان رجلا أم امرأة لئلا ينجسوا مخيمهم، حيث أنا ساكن في وسطهم».","5:4":"فنفذ بنو إسرائيل الأمر، وعزلوهم إلى خارج المخيم، طبقا لما أمر الرب موسى.","5:5":"وقال الرب لموسى:","5:6":"«أوص بني إسرائيل إذا ارتكب رجل أو امرأة خطيئة السرقة وخان الرب، فقد أذنبت تلك النفس،","5:7":"وعليها أن تعترف بخطيئتها التي اقترفتها، وترد ما أذنبت به، بعد أن تضيف عليه خمسه وتدفعه لمن أذنبت بحقه.","5:8":"وإن لم يكن للرجل المسروق، إذا مات، ولي يرد إليه المسروق، فليكن المسروق للرب. يأخذه الكاهن لنفسه، فضلا عن كبش الكفارة الذي يكفر به عنه.","5:9":"وتكون كل التقدمات المقدسة التي يقربها الإسرائيليون للكاهن نصيبا له.","5:10":"وكذلك أقداس الإنسان تكون له. وإذا أعطى إنسان شيئا للكاهن فله يكون».","5:11":"وقال الرب لموسى:","5:12":"«أوص بني إسرائيل وقل لهم: إذا غوت امرأة رجل وخانته","5:13":"بزناها مع رجل آخر، وخفي الأمر على زوجها، ولم يقم عليها دليل ولم يقبض عليها متلبسة بزناها.","5:14":"وإذا اعترت زوجها الغيرة وارتاب بزوجته وكانت نجسة، أو غار على امرأته مع أنها طاهرة.","5:15":"فليحضر الرجل امرأته إلى الكاهن، ويأتي معه بقربانها عشر الإيفة (نحو لترين ونصف اللتر) من دقيق الشعير. لا يصب عليه زيتا، ولا يضع عليه لبانا، لأنه تقدمة غيرة، تقدمة تذكرة تذكر بذنب.","5:16":"فيجعل الكاهن الزوجة تمثل أمام الرب،","5:17":"ثم يأخذ ماء مقدسا في إناء من خزف ويلتقط بعض غبار أرض المسكن ويضعه في الماء.","5:18":"ويكشف رأس الزوجة، ويضع في يديها تقدمة التذكار التي هي تقدمة الغيرة، ويحمل الكاهن بيده ماء اللعنة المر.","5:19":"ويستحلف الكاهن المرأة قائلا لها: إن كان رجل آخر لم يضاجعك، ولم تخوني زوجك، فأنت بريئة من ماء اللعنة المر هذا.","5:20":"ولكن إن كنت قد خنت زوجك وتنجست بمضاجعة رجل غيره.","5:21":"فليجعل الرب لعنة شعبك عليك، فيتبرأون منك عندما يجعل الرب فخذك يذوي وبطنك يتورم.","5:22":"وليدخل ماء اللعنة هذا في أحشائك ليسبب ورما لبطنك، وليذو فخذك». فتقول المرأة: «آمين. آمين».","5:23":"«ثم يدون الكاهن هذه اللعنات في درج ويمحوها بالماء المر؛","5:24":"ويسقي المرأة ماء اللعنة المر الذي محا به اللعنات فيدخل فيها ماء اللعنة ليسبب لها آلام المرارة.","5:25":"ثم يأخذ الكاهن من يد المرأة تقدمة الغيرة، ويرجحها أمام الرب، ثم يقدمها إلى المذبح.","5:26":"ويتناول ملء قبضته منها ويحرقه على المذبح، وبعد ذلك يسقي المرأة الماء.","5:27":"فإن كانت المرأة قد تنجست وخانت زوجها، فإنها حين تشرب الماء الجالب اللعنة يسبب لها آلام مرارة، فيتورم بطنها ويذوي فخذها، وتصبح المرأة لعنة في وسط شعبها.","5:28":"أما إن كانت بريئة طاهرة، فإنها تتبرأ ولا تصبح عاقرا.","5:29":"إذا، هذه هي شريعة الغيرة التي تطبقونها إذا خانت امرأة زوجها وتنجست.","5:30":"أو إذا اعترت الغيرة رجلا، فغار على زوجته، فعليه أن يأتي بالمرأة أمام الرب ويمارس عليها الكاهن كل هذه الشعائر.","5:31":"ولا يعاقب الرجل إذا أصاب الضرر زوجته المذنبة، أما هي فتحمل قصاص خطيئتها».","6:1":"وقال الرب لموسى:","6:2":"«أوص بني إسرائيل وقل لهم: أي رجل أو امرأة تعهد بنذر خاص يتنسك فيه للرب،","6:3":"فليمتنع عن الخمر والمسكر، ولا يشرب خل الخمر ولا خل المسكر أو نقيع العنب، ولا يأكل عنبا رطبا ولا يابسا.","6:4":"لا يذق كل أيام نذره شيئا من نتاج الكرمة حتى بذور العنب وقشره.","6:5":"ولا يحلق رأسه طوال مدة نذره إلى أن تتم الأيام التي نذر فيها نفسه للرب، لأنه مقدس، فعليه أن يرخي خصل شعر رأسه.","6:6":"لا يقرب جسد ميت كل أيام نذره للرب.","6:7":"سواء كان الميت أباه أم أمه أم أخاه أم أخته فلا يتنجس من أجلهم عند موتهم، لأن رمز نسك إلهه على رأسه.","6:8":"ويكون كل أيام نذره مقدسا للرب.","6:9":"وإذا تنجس شعر انتذاره على أثر موت أحد عنده بغتة، يحلق شعره بعد ذلك بسبعة أيام فيطهر.","6:10":"ثم في اليوم الثامن يأتي بيمامتين أو فرخي حمام إلى الكاهن عند مدخل خيمة الاجتماع.","6:11":"فيقدم الكاهن أحدهما ذبيحة خطيئة والآخر محرقة، ويكفر عنه خطيئته لوجوده أمام جثة ميت، ويقدس رأسه في ذلك اليوم بعينه.","6:12":"ولا تحسب له أيام نذره التي سبقت تنجيسه بسبب الميت، وعليه أن يبدأ عد أيام فترة نذره من جديد، ويأتي بحمل حولي ويقدمه ذبيحة إثم.","6:13":"وهذه هي شريعة النذير عندما يستوفي أيام نذره: يأتي إلى مدخل خيمة الاجتماع،","6:14":"فيقدم قربانه للرب حملا حوليا، بلا عيب، ليكون محرقة، ونعجة حولية، صحيحة، لتكون ذبيحة خطيئة، وكبشا سليما ليكون ذبيحة سلامة.","6:15":"فضلا عن سل من كعك فطير معجون بزيت، ورقاق غير مختمرة مدهونة بالزيت مع تقدمة دقيق وخمر.","6:16":"فيقدمها الكاهن أمام الرب ذبيحة خطيئته ومحرقته.","6:17":"ثم يقرب كبش ذبيحة السلامة مع سل كعك الفطير. وأخيرا يرفع الكاهن تقدمة الدقيق والخمر.","6:18":"ثم يحلق النذير شعر انتذاره عند مدخل خيمة الاجتماع، ويحرقه على نار ذبيحة السلامة.","6:19":"ثم يأخذ الكاهن كتف الكبش بعد سلقه، وكعكة فطير واحدة ورقاقة واحدة. ويضعها بين يدي النذير بعد حلقه شعر انتذاره.","6:20":"ويرجحها الكاهن أمام الرب، فتكون نصيبا مقدسا للكاهن مع صدر الترجيح وساق الذبيحة. وبعد ذلك يشرب النذير خمرا.","6:21":"هذه هي شريعة النذير الذي ينذر تقدمة للرب وقت نسكه، فضلا عن تقدماته الطوعية التي يبذلها. وعليه أن يفي بما نذر حسب شريعة انتذاره».","6:22":"وقال الرب لموسى:","6:23":"«أوص هرون وأبناءه قائلا: هذا ما يباركون به بني إسرائيل قائلين لهم:","6:24":"يباركك الرب ويحرسك.","6:25":"يضيء الرب بوجهه عليك ويرحمك.","6:26":"يلتفت الرب بوجهه إليك ويمنحك سلاما.","6:27":"وهكذا يجعلون اسمي على بني إسرائيل وأنا أباركهم».","7:1":"وعندما انتهى موسى من نصب المسكن ومسحه وتقديسه، مع سائر أوانيه، والمذبح مع أمتعته كلها التي مسحها وقدسها،","7:2":"أحضر رؤساء أسباط إسرائيل قرابينهم، وهم قادة عشائرهم أيضا، الذين أشرفوا على تنظيم الإحصاء.","7:3":"وجاءوا بها أمام الرب، فكانت ست عربات مغطاة يجرها اثنا عشر ثورا، ثور لكل رئيس وعربة لكل رئيسين، وقدموها أمام خيمة الاجتماع.","7:4":"فقال الرب لموسى:","7:5":"«اقبل القرابين منهم لتستخدم في عمل خيمة الاجتماع، وأعطها للاويين؛ لكل واحد حسب خدمته المنوطة به».","7:6":"فأخذ موسى العربات والثيران وقدمها للاويين،","7:7":"فأعطى اثنين من العربات مع أربعة ثيران لبني جرشون، وفقا لما تتطلبه خدمتهم،","7:8":"وأربعا من العربات وثمانية ثيران لبني مراري، وفقا لما تتطلبه خدمتهم تحت إشراف إيثامار بن هرون الكاهن.","7:9":"أما بنو قهات فلم يحظوا بنصيب منها إذ توجب عليهم أن يحملوا الأشياء المقدسة على أكتافهم.","7:10":"وعند تدشين المذبح ومسحه قدم الرؤساء قرابينهم أمام المذبح.","7:11":"فقال الرب لموسى: «ليحضر رئيس واحد في كل يوم قربانه لتدشين المذبح».","7:12":"فكان نحشون بن عميناداب من سبط يهوذا هو الذي قدم قربانه في اليوم الأول،","7:13":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان بتقدمة من دقيق بزيت،","7:14":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:15":"وثورا واحدا وكبشا واحدا وخروفا واحدا حوليا، لتكون كلها محرقة،","7:16":"وتيسا واحدا لذبيحة خطيئة.","7:17":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان نحشون بن عميناداب.","7:18":"وفي اليوم الثاني أحضر نثنائيل بن صوغر رئيس سبط يساكر قربانه،","7:19":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان بتقدمة من دقيق معجون بزيت،","7:20":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:21":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:22":"وتيسا واحدا لذبيحة خطيئة.","7:23":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة فكانت هذه قربان نثنائيل بن صوغر.","7:24":"وفي اليوم الثالث أحضر رئيس سبط زبولون، أليآب بن حيلون قربانه","7:25":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان بتقدمة من دقيق معجون بزيت،","7:26":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:27":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:28":"وتيسا واحدا لذبيحة خطيئة.","7:29":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة فكانت هذه قربان أليآب بن حيلون.","7:30":"وفي اليوم الرابع أحضر رئيس بني رأوبين، أليصور بن شديئور قربانه،","7:31":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان بتقدمة دقيق معجون بزيت،","7:32":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:33":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:34":"وتيسا واحدا لذبيحة خطيئة.","7:35":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة فكانت هذه قربان أليصور بن شديئور.","7:36":"وفي اليوم الخامس أحضر رئيس بني شمعون، شلوميئيل بن صوريشداي قربانه،","7:37":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:38":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:39":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:40":"وتيسا واحدا لذبيحة خطيئة.","7:41":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان شلوميئيل بن صوريشداي.","7:42":"وفي اليوم السادس أحضر رئيس بني جاد، ألياساف بن دعوئيل قربانه،","7:43":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:44":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:45":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:46":"وتيسا واحدا لذبيحة خطيئة.","7:47":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان ألياساف بن دعوئيل.","7:48":"وفي اليوم السابع أحضر رئيس بني أفرايم أليشمع بن عميهود قربانه،","7:49":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:50":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:51":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:52":"وتيسا واحدا لذبيحة خطيئة.","7:53":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان أليشمع بن عميهود.","7:54":"وفي اليوم الثامن أحضر رئيس بني منسى، جمليئيل بن فدهصور قربانه،","7:55":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:56":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:57":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:58":"وتيسا واحدا لذبيحة خطيئة.","7:59":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان جمليئيل بن فدهصور.","7:60":"وفي اليوم التاسع أحضر رئيس بني بنيامين، أبيدن بن جدعوني قربانه،","7:61":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:62":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:63":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:64":"وتيسا واحدا لذبيحة خطيئة.","7:65":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان أبيدن بن جدعوني.","7:66":"وفي اليوم العاشر أحضر رئيس بني دان، أخيعزر بن عميشداي قربانه،","7:67":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:68":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:69":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:70":"وتيسا واحدا لذبيحة خطيئة.","7:71":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان أخيعزر بن عميشداي.","7:72":"وفي اليوم الحادي عشر أحضر رئيس أشير، فجعيئيل بن عكرن قربانه،","7:73":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:74":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:75":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:76":"وتيسا واحدا لذبيحة خطيئة.","7:77":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان فجعيئيل بن عكرن.","7:78":"وفي اليوم الثاني عشر أحضر رئيس بني نفتالي، أخيرع بن عينن قربانه،","7:79":"فكان طبقا فضيا واحدا وزنه مئة وثلاثون شاقلا (نحو ألف وخمس مئة وستين جراما) ومنضحة فضية واحدة وزنها سبعون شاقلا (نحو ثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس. وكلا الإناءين مملوءان من دقيق معجون بزيت،","7:80":"وصحنا واحدا وزنه عشرة شواقل (نحو مئة وعشرين جراما) من ذهب مليئا بالبخور،","7:81":"وثورا واحدا وكبشا واحدا وخروفا حوليا واحدا، لتكون كلها محرقة،","7:82":"وتيسا واحدا لذبيحة خطيئة.","7:83":"كما قرب ثورين وخمسة كباش وخمسة تيوس وخمسة حملان حولية لذبيحة السلامة. فكانت هذه قربان أخيرع بن عينن.","7:84":"فهذه كانت جملة تقدمات رؤساء أسباط إسرائيل يوم تدشين المذبح ومسحه، اثنا عشر طبقا فضيا، واثنتا عشرة منضحة فضية واثنا عشر صحنا ذهبيا.","7:85":"وكان وزن كل طبق مئة وثلاثين شاقلا (نحو ألف وخمس مئة وستين جراما) من الفضة، ووزن كل منضحة سبعين شاقلا (نحو ثماني مئة وأربعين جراما) فكان مجموع وزن فضة الآنية ألفين وأربع مئة شاقل (نحو ثمانية آلاف وثماني مئة وأربعين جراما) وفقا للوزن المعتمد في القدس.","7:86":"أما صحون الذهب الاثنا عشر المملوءة بالبخور، فكان وزن كل منها عشرة شواقل (نحو مئة وعشرين جراما) وفقا للوزن المعتمد في القدس وهي بمجموعها تعادل مئة وعشرين شاقلا (نحو ألف وأربعة مئة وأربعين جراما).","7:87":"وكان مجموع ثيران المحرقة اثني عشر ثورا، والكباش اثني عشر كبشا، والخراف الحولية اثني عشر خروفا فضلا عن تقدمتها، والتيوس الاثني عشر لذبيحة الخطيئة.","7:88":"وكان مجموع ثيران ذبيحة السلامة أربعة وعشرين ثورا، والكباش ستين كبشا، والتيوس ستين تيسا، والحملان الحولية ستين حملا. هذه قرابين تدشين المذبح بعد مسحه.","7:89":"وعندما دخل موسى إلى خيمة الاجتماع ليتكلم مع الرب سمع الصوت يخاطبه من على الغطاء الذي فوق تابوت الشهادة من بين الكروبين، فكلمه.","8:1":"وقال الرب لموسى:","8:2":"«أوص هرون وقل له: متى أضأت سرج المنارة السبعة، فاجعل نورها ينعكس إلى الأمام».","8:3":"فنفذ هرون الأمر، إذ جعل أنوار المنارة تنعكس أمامها كما أمر الرب موسى.","8:4":"أما المنارة فكانت مطروقة من ذهب هي وساقها وزهرها وفقا للمثال الذي أراه الرب لموسى.","8:5":"وقال الرب لموسى:","8:6":"«أفرز اللاويين من بين بني إسرائيل وطهرهم.","8:7":"وهذا ما تفعله لتطهيرهم: رش عليهم ماء الخطيئة، ثم ليحلقوا شعر جسدهم، ويغسلوا ثيابهم فيتطهروا.","8:8":"ثم ليحضروا ثورا مع تقدمة من دقيق معجون بزيت، وعجلا آخر ليكون ذبيحة خطيئة.","8:9":"وتوقف اللاويين أمام خيمة الاجتماع وتجمع كل شعب إسرائيل.","8:10":"وتقدم اللاويين أمام الرب فيضع بنو إسرائيل أيديهم عليهم.","8:11":"وليرجح هرون يديه أمام الرب كرمز لتقديم اللاويين من بين بني إسرائيل، ليقوموا بخدمة الرب.","8:12":"ثم يضع اللاويون أيديهم على رأسي العجلين، فتقرب أحدهما ذبيحة خطيئة والآخر محرقة للرب تكفيرا عن اللاويين.","8:13":"واجعل اللاويين يقفون أمام هرون وأبنائه وقدمهم كتقدمة ترجيح للرب.","8:14":"وأفرز اللاويين من بين شعب إسرائيل ليكونوا ملكا لي","8:15":"ثم يقبل اللاويون على خدمة خيمة الاجتماع، فتطهرهم وتجعلهم تقدمة ترجيح،","8:16":"لأنهم قد وهبوا لي من بين بني إسرائيل، فقد استعضت بهم عن كل بكر فاتح رحم من إسرائيل،","8:17":"لأن كل بكر في إسرائيل من الناس والبهائم هو لي، إذ قدستهم لي يوم قضيت على كل بكر في ديار مصر.","8:18":"فاستعضت باللاويين عن كل بكر لي من شعب إسرائيل.","8:19":"وقد وهبت اللاويين لهرون وأبنائه من بين شعب إسرائيل، ليقوموا على خدمة خيمة الاجتماع، عوضا عن شعب إسرائيل، وللتكفير عنهم، لئلا يتفشى وبَأ في إسرائيل عند اقترابهم من القدس».","8:20":"ففعل موسى وهرون وشعب إسرائيل للاويين، بكل دقة، جميع ما أمر الرب به","8:21":"فتطهر اللاويون وغسلوا ثيابهم وأحضرهم هرون أمام الرب كتقدمة ترجيح وكفر عنهم تطهيرا لهم.","8:22":"وبعد ذلك أقبل اللاويون على خدمة خيمة الاجتماع تحت إشراف هرون وأبنائه، وهكذا تم تنفيذ كل ما أمر الرب به بشأن اللاويين.","8:23":"وقال الرب لموسى:","8:24":"«هذه هي شريعة اللاويين: كل لاوي عمره خمس وعشرون سنة فما فوق، يجند في خدمة خيمة الاجتماع.","8:25":"ولكنهم يتقاعدون عن الخدمة عند بلوغهم الخمسين من العمر.","8:26":"إنما يمكنهم بعد سن الخمسين أن يساعدوا إخوتهم القائمين بواجباتهم، ولكنهم لا يتولون هم الخدمة. فهذا ما يتوجب عليك أن تعهد به للاويين من مسئوليات».","9:1":"وفي الشهر الأول من السنة الثانية لخروجهم من ديار مصر، قال الرب لموسى في صحراء سيناء:","9:2":"«ليحتفل شعب إسرائيل بالفصح في أوانه.","9:3":"احتفلوا به في اليوم الرابع عشر من الشهر الأول بين العشاءين قائمين بكل شعائره وأحكامه».","9:4":"فأمر موسى الإسرائيليين أن يحتفلوا بالفصح،","9:5":"فاحتفلوا به في صحراء سيناء في اليوم الرابع عشر من الشهر الأول (أي شهر آذار ; مارس) بين العشاءين، طبقا لكل ما أمر الرب به موسى.","9:6":"إلا أن قوما كانوا قد لمسوا ميتا فتنجسوا، فلم يحل لهم الاحتفال بالفصح في ذلك اليوم، فمثلوا أمام موسى وهرون،","9:7":"وسألوه: «إننا متنجسون لأننا لمسنا ميتا، فلماذا نحرم من تقديم قربان الرب في أوانه من دون شعب إسرائيل؟»","9:8":"فأجابهم موسى: «انتظروا ريثما يبلغني الرب أمره بشأنكم».","9:9":"فقال الرب لموسى:","9:10":"«أوص بني إسرائيل وقل لهم: في وسع كل إنسان منكم ومن أعقابكم تنجس للمسه ميتا أو كان في سفر بعيد، أن يحتفل بفصح الرب.","9:11":"احتفلوا به في اليوم الرابع عشر من الشهر الثاني (أي شهر نيسان ; أبريل) بين العشاءين فتأكلوا الفصح مع فطير وأعشاب مرة.","9:12":"لا تتركوا منه شيئا إلى الصباح، ولا تكسروا منه عظما. احتفلوا به طبقا لشعائر الفصح كلها.","9:13":"ولكن من كان طاهرا وليس في سفر، وأغفل الاحتفال بالفصح، فإنه يستأصل من بين شعبه، لأنه لم يقدم قربان الرب في أوانه. ذلك الإنسان يتحمل عقاب خطيئته.","9:14":"وإذا حل عندكم غريب فليحتفل بالفصح طبقا لشعائر الفصح وأحكامه، فتكون لكم فريضة واحدة للغريب وللمواطن على حد سواء».","9:15":"وفي اليوم الذي نصب فيه المسكن غطت السحابة خيمة الشهادة. وفي المساء بدا وكأن على المسكن نارا بقيت حتى الصباح.","9:16":"واستمر الأمر على هذه الحال، إذ كانت السحابة تغطي المسكن نهارا، وتتحول إلى ما يشبه النار ليلا.","9:17":"وكلما ارتفعت السحابة عن الخيمة كان على شعب إسرائيل الارتحال، وحيثما حلت السحابة كانوا ينزلون هناك،","9:18":"فكان بنو إسرائيل يرتحلون حسب قول الرب، وبموجب أمره كانوا ينزلون، ويمكثون مقيمين طوال أيام حلول السحابة على المسكن.","9:19":"وإن طال أمد حلول السحابة على المسكن أياما كثيرة، كان شعب إسرائيل يطيعون أمر الرب، ويلبثون مقيمين لا يرتحلون.","9:20":"وكانت السحابة تخيم أحيانا على المسكن أياما قليلة، فكان الإسرائيليون ينزلون حسب قول الرب، ووفقا لأمره كانوا يرتحلون.","9:21":"وإذا حلت السحابة من المساء إلى الصباح ثم ارتفعت عند الصباح فإنهم كانوا يرتحلون، وكذلك إن حلت يوما وليلة ثم ارتفعت، كانوا يرتحلون.","9:22":"أو إن مكثت السحابة يومين أو شهرا أو سنة، كان الإسرائيليون يقيمون ولا يرتحلون مادامت السحابة حالة على المسكن. ومتى ارتفعت كانوا يرتحلون.","9:23":"وهكذا كانوا في نزولهم ورحيلهم يأتمرون بقول الرب، فأطاعوا أوامر الرب طبقا لما أوصى به موسى.","10:1":"وقال الرب لموسى:","10:2":"«اصنع لك بوقين من فضة مطروقة تستخدمهما لدعوة الشعب، ولإعلان نفير الرحيل،","10:3":"فحالما ينفخ فيهما يجتمع إليك الشعب عند مدخل خيمة الاجتماع.","10:4":"أما إذا نفخ في بوق واحد، يتوافد إليك رؤساء أسباط إسرائيل.","10:5":"وعندما يرتفع نفير هتاف، ترتحل الأسباط المخيمة إلى الشرق،","10:6":"وإذا ارتفع نفير هتاف ثان ترتحل الأسباط النازلة إلى الجنوب، وهكذا يعلن عن الارتحال بنفير الهتاف.","10:7":"أما عند جمع الشعب، فانفخوا بالبوقين، ولكن من غير هتاف،","10:8":"ويكون أبناء هرون هم النافخون بالأبواق، فريضة دائمة لكم جيلا بعد جيل.","10:9":"وإن ذهبتم لمحاربة عدو في أرضكم يضر بكم، فاضربوا بالأبواق، فأذكركم وأخلصكم من أعدائكم.","10:10":"انفخوا في الأبواق أيضا في أيام فرحكم وفي أعيادكم ورؤوس شهوركم، وكذلك على محرقاتكم وذبائح سلامتكم، فتكون لكم تذكارا أمامي. أنا الرب إلهكم».","10:11":"وفي اليوم العشرين من الشهر الثاني (أي شهر نيسان ; أبريل) من السنة الثانية (العبرية) ارتفعت السحابة عن مسكن الشهادة،","10:12":"فارتحل بنو إسرائيل في صحراء سيناء من مكان إلى آخر إلى أن استقرت السحابة في برية فاران.","10:13":"وكانت هذه أول مرة يرتحلون فيها بموجب التنظيم الجديد الذي أمر به الرب على لسان موسى،","10:14":"فقد ارتحلت أولا مخيمات سبط يهوذا طبقا لعشائرهم، وعلى رأسهم نحشون بن عميناداب.","10:15":"ثم عشائر سبط يساكر، وعلى رأسهم نثنائيل بن صوغر،","10:16":"وتلاهم سبط زبولون، وعلى رأسه آليآب بن حيلون،","10:17":"ثم أنزل المسكن، فارتحل بنو جرشون وبنو مراري حاملين المسكن،","10:18":"وأعقبتهم مخيمات سبط رأوبين وفقا لعشائرهم، وعلى رأسهم أليصور بن شديئور.","10:19":"ثم عشائر سبط شمعون، وعلى رأسهم شلوميئيل بن صوريشداي،","10:20":"وتبعتهم عشائر سبط جاد، وعلى رأسهم ألياساف بن دعوئيل،","10:21":"ثم ارتحل القهاتيون حاملين المقدس إلى حيث كان المسكن قد أقيم في انتظارهم.","10:22":"وارتحلت على أثرهم مخيمات أفرايم حسب عشائرها وعلى رأسها أليشمع بن عميهود،","10:23":"ثم سبط منسى وعلى رأسه جمليئيل بن فدهصور،","10:24":"وتبعهم سبط بنيامين، وعلى رأسه أبيدن بن جدعوني،","10:25":"ثم ارتحلت مخيمات سبط دان برايته مع جميع عشائره، في مؤخرة الجماعة، وكان على رأسه أخيعزر بن عميشداي.","10:26":"وسبط أشير وعلى رأسه فجعيئيل بن عكرن،","10:27":"وسبط نفتالي وعلى رأسه أخيرع بن عينن،","10:28":"فكان هذا هو النظام الذي سارت عليه أسباط بني إسرائيل في أثناء رحيلهم.","10:29":"وقال موسى لحميه حوباب بن رعوئيل المدياني: «إننا راحلون إلى الأرض التي وعد الرب أن يهبها لنا، فتعال معنا، فنحسن إليك، لأن الرب قد وعد أن يحسن إلى إسرائيل».","10:30":"فقال له: «لا أذهب، بل دعني أمضي إلى أرضي وعشيرتي».","10:31":"فقال موسى: «لا تتركنا لأنك تعرف مسالك الصحراء ومواضع الإقامة فيها، فتكون لنا دليلا.","10:32":"وإن رافقتنا فإننا نحسن إليك بنفس الإحسان الذي يحسن الرب به إلينا».","10:33":"فارتحلوا من عند جبل الرب مسيرة ثلاثة أيام، وكان تابوت الرب يتقدمهم باحثا لهم عن موضع إقامة.","10:34":"وكانت سحابة الرب تظللهم نهارا في أثناء ارتحالهم من المخيم،","10:35":"وكان موسى يقول عند ارتحال التابوت: «قم يارب وبدد أعداءك فيهرب مبغضوك من أمامك»","10:36":"وكان يقول عند حلوله: «ارجع يارب إلى عشرات ألوف إسرائيل».","11:1":"وراح الشعب يتذمر في مسمع الرب وكأن شرا أصابهم، فاحتدم غضب الرب عليهم، واندلعت فيهم ناره وأحرقت طرف المخيم،","11:2":"فصرخوا إلى موسى، فصلى موسى إلى الرب فخمدت النار،","11:3":"فدعي ذلك المكان «تبعيرة» (ومعناه: اشتعال) لأن نار الرب اشتعلت فيهم.","11:4":"واشتهى أخلاط الأمم المقيمين بين بني إسرائيل، ممن خرجوا معهم من مصر، طعام مصر، فعاد بنو إسرائيل يبكون قائلين: «من يطعمنا لحما؟","11:5":"لقد تذكرنا سمك مصر الذي كنا نأكله مجانا، والقثاء والبطيخ والكرات والبصل والثوم،","11:6":"أما الآن فقد فقدنا شهيتنا وهزلنا، وليس أمام أعيننا سوى هذا المن».","11:7":"وكان المن في حجم بذور الكزبرة، وشكله مماثلا للمقل.","11:8":"وكان الشعب يطوفون ليجمعوه ثم يطحنونه بالرحى أو يدقونه في الهاون ويطبخونه في القدور أو يخبزونه على حجارة محماة. وكان طعمه كطعم قطائف بزيت.","11:9":"وكان المن ينزل بنزول الندى على المخيم في أثناء الليل.","11:10":"فلما سمع موسى بكاء جميع أفراد الشعب، كل أمام باب خيمته، ورأى احتدام غضب الرب الشديد اعتراه الاستياء.","11:11":"فقال موسى للرب: «لماذا أسأت إلى عبدك ولم ترض عنه حتى إنك حملته مسئولية هذا الشعب؟","11:12":"ألعلي حبلت به أو ولدته، حتى تقول لي احمله في حضنك كما يحمل المربي الرضيع، وقده إلى الأرض التي وعدت بها آباءه.","11:13":"من أين أجيء بلحم يكفي جميع هذا الشعب؟ فإنهم يبكون إلي قائلين: أعطنا لحما لنأكل.","11:14":"إنني عاجز عن حمل عبء هذا الشعب وحدي لأنه ثقيل علي.","11:15":"إن كنت ستعاملني هكذا، فاقتلني، إن حظيت برضاك، فلا أشهد بليتي».","11:16":"فقال الرب لموسى: «اجمع إلي سبعين رجلا من رؤساء إسرائيل ممن تعلم أنهم حقا شيوخ الشعب وعرفاؤه، وأقبل بهم إلى خيمة الاجتماع ليمثلوا معك هناك.","11:17":"فأنزل وأخاطبك هناك، وآخذ من الروح الذي عليك وأضع عليهم، فيعينونك في حمل مسئولية الشعب، فلا تحملها أنت وحدك.","11:18":"وقل للشعب، أن يتقدسوا للغد، فيأكلوا لحما، لأنكم قد بكيتم في أذني الرب متسائلين: من يطعمنا لحما؟ لقد كان لنا خير في مصر. إن الرب سيعطيكم لحما فتأكلون.","11:19":"وستأكلونه لا ليوم واحد، ولا ليومين، ولا لخمسة أيام أو لعشرة أيام ولا لعشرين يوما،","11:20":"بل لشهر كامل إلى أن تعافوه ويخرج من أنوفكم، لأنكم رفضتم الرب الذي في وسطكم، وبكيتم لديه قائلين: لماذا خرجنا من مصر؟»","11:21":"فقال موسى: «هذا الشعب الذي أنا قائم في وسطه نحو ست مئة ألف رجل، ماعدا النساء والأطفال، وأنت تقول إنك ستعطيهم لحما ليأكلوا شهرا كاملا،","11:22":"فمهما ذبح من غنم وبقر أيكفيهم؟ أم يكفيهم لو جمع كل سمك البحر؟»","11:23":"فقال الرب لموسى: «هل تعجز يد الرب؟ انتطر الآن لترى إن كان يتحقق كلامي أم لا».","11:24":"فخرج موسى وكلم الشعب بما قاله الرب، وجمع سبعين رجلا من رؤسائهم وأوقفهم حول الخيمة.","11:25":"فنزل الرب في سحابة وخاطبه، وأخذ من الروح الحال عليه ووضعه على السبعين رئيسا. فلما حل عليهم الروح تنبأوا لفترة وتوقفوا.","11:26":"وكان قد بقي اثنان من الشيوخ المسجلين بين السبعين في المخيم لم يأتيا إلى الخيمة، اسم أحدهما ألداد، واسم الآخر ميداد. فحل عليهما الروح فتنبآ في المخيم.","11:27":"فأسرع أحد الشبان وأخبر موسى بذلك،","11:28":"فقال يشوع بن نون، مساعد موسى منذ حداثته: «ياسيدي، امنعهما!»","11:29":"غير أن موسى قال له: «هل ملأتك غيرة علي؟ ليت كل شعب الرب يصبحون أنبياء يحل عليهم الرب بروحه».","11:30":"ثم رجع موسى وشيوخ إسرائيل إلى المخيم.","11:31":"فهبت ريح من عند الرب ساقت السماني من جهة البحر وأسقطتها على المخيم، نحو مسيرة يوم، من كلا جهتيه وحواليه، وتراكم حتى بلغ ارتفاعه ذراعين (نحو متر) فوق وجه الأرض.","11:32":"فهب الشعب طوال ذلك النهار والليل، وكل نهار اليوم التالي يلتقطون السماني. فكانت أقل كمية جمعت حوالي عشرة حوامر (نحو ألفين وأربع مئة لتر)، ثم نشروها حول المخيم لتجف.","11:33":"وإذ كانوا مازالوا يمضغون اللحم، احتدم غضب الرب عليهم، فأفشى بينهم وبأ مميتا،","11:34":"فدعوا المكان «قبروت هتأوة» (ومعناه قبور الشهوة) لأنهم هناك دفنوا القوم المشتهين.","11:35":"ثم ارتحل الشعب من قبروت هتأوة إلى حضيروت ومكثوا فيها.","12:1":"وانتقدت مريم وهرون موسى لزواجه من امرأة كوشية،","12:2":"وقالا: «هل كلم الرب موسى وحده؟ ألم يكلمنا نحن أيضا؟» فسمع الرب.","12:3":"أما موسى فقد كان أكثر حلما من جميع الناس الذين على وجه الأرض.","12:4":"فقال الرب حالا لموسى وهرون ومريم: «اذهبوا أنتم الثلاثة إلى خيمة الاجتماع». فمضى ثلاثتهم.","12:5":"فنزل الرب في عمود سحاب وحل عند باب الخيمة، ونادى هرون ومريم، فتقدما وحدهما،","12:6":"فقال: «اسمعا كلامي: إن كان بينكم نبي للرب فإني أستعلن له بالرؤيا، وأكلمه بالحلم،","12:7":"أما عبدي موسى فلست أعامله هكذا، بل هو أمين في بيتي،","12:8":"لذلك أكلمه وجها لوجه، وبوضوح من غير ألغاز، ويعاين صورة الرب. فلماذا جرؤتما على انتقاد عبدي موسى؟»","12:9":"واحتد غضب الرب عليهما، ثم مضى عنهما.","12:10":"فلما ارتفعت السحابة عن خيمة الاجتماع، إذا مريم برصاء كالثلج فالتفت هرون وموسى نحو مريم، وإذا هي مصابة بالبرص.","12:11":"فقال هرون لموسى: «أرجوك ياسيدي، لا تحملنا الخطيئة التي ارتكبناها كالحمقى، وأسأنا بها إليك.","12:12":"ولا تجعل مريم كالجنين الميت الخارج من رحم أمه وقد تهرأ نصف لحمه».","12:13":"فصرخ موسى إلى الرب قائلا: «اللهم اشفها».","12:14":"فأجابه الرب: «لو أن أباها بصق في وجهها، أما كانت تمكث خجلة سبعة أيام؟ فلتحجز خارج المخيم سبعة أيام وبعد ذلك ترجع».","12:15":"فحجزت مريم سبعة أيام خارج المخيم، ولم يرتحل الشعب حتى عادت مريم،","12:16":"وبعد ذلك ارتحل الشعب من حضيروت ونزلوا في صحراء فاران.","13:1":"ثم قال الرب لموسى:","13:2":"«أرسل جواسيس إلى أرض كنعان التي أنا واهبها لبني إسرائيل. أرسل رئيسا من كل سبط ممثلا له».","13:3":"فأرسل موسى ممثلي الشعب الرؤساء من صحراء فاران طبقا لأمر الرب.","13:4":"وهم: شموع بن زكور عن سبط رأوبين،","13:5":"شافاط بن حوري عن سبط شمعون،","13:6":"كالب بن يفنة عن سبط يهوذا،","13:7":"يجآل بن يوسف عن سبط يساكر،","13:8":"هوشع بن نون عن سبط أفرايم،","13:9":"فلطي بن رافو عن سبط بنيامين،","13:10":"جديئيل بن سودي عن سبط زبولون،","13:11":"جدي بن سوسي من سبط منسى عن سبط يوسف،","13:12":"عميئيل بن جملي عن سبط دان،","13:13":"ستور بن ميخائيل عن سبط أشير،","13:14":"نحبي بن وفسي عن سبط نفتالي،","13:15":"جأوئيل بن ماكي عن سبط جاد.","13:16":"هذه هي أسماء الرجال الذين أرسلهم موسى ليتجسسوا أرض كنعان، وآنذاك غير موسى اسم هوشع بن نون إلى يشوع.","13:17":"وعندما أطلقهم موسى ليتجسسوا أرض كنعان قال لهم: «انطلقوا من هنا نحو الجنوب، ثم اصعدوا إلى الجبل،","13:18":"واستكشفوا البلاد وأوضاعها وهل شعبها المقيم فيها قوي أم ضعيف؟ أكثير هو أم قليل؟","13:19":"وما هي طبيعة الأرض الساكن فيها، أصالحة هي أم رديئة؟ وما هي المدن التي هو قاطن فيها؟ أمخيمات هي أم حصون؟","13:20":"وكيف هي أرضه: أخصبة أم قاحلة؟ أفيها شجر أم جرداء؟ تشجعوا وأحضروا عينة من ثمر الأرض». وكان الموسم عندئذ موسم باكورات العنب.","13:21":"فمضوا وتجسسوا الأرض، ابتداء من صحراء صين إلى رحوب على مشارف حماة.","13:22":"واجتازوا صحراء النقب حتى وصلوا حبرون حيث تقيم قبائل بني عناق: أخيمان وشيشاي وتلماي. وكانت حبرون قد بنيت قبل مدينة صوعن المصرية بسبع سنوات.","13:23":"ثم قدموا على وادي أشكول، فقطفوا فرعا من كرمة عنب فيه عنقود واحد، حملوه بعصا على كتفي اثنين منهم، فضلا عن شيء من التين والرمان.","13:24":"فدعي ذلك الموضع وادي أشكول (ومعناه: وادي العنقود) بسبب عنقود العنب الذي قطفه الإسرائيليون من هناك.","13:25":"وبعد أربعين يوما رجعوا من استكشاف الأرض.","13:26":"فأقبلوا على موسى وهرون وسائر شعب إسرائيل في صحراء فاران في قادش، وبلغوهم بما شاهدوه، وأروهم ثمر الأرض.","13:27":"وقالوا: «قد انطلقنا إلى الأرض التي أرسلتنا إليها، فوجدناها تفيض حقا لبنا وعسلا، وهذه هي ثمارها،","13:28":"غير أن الشعب المستوطن فيها بالغ القوة ومدنه منيعة وعظيمة جدا. كما شاهدنا هناك بني عناق،","13:29":"فالعمالقة مقيمون في أرض الجنوب، والحثيون واليبوسيون والأموريون متمنعون في الجبل، والكنعانيون مستوطنون عند البحر وعلى محاذاة الأردن».","13:30":"ولكن كالب هدأ روع الشعب الماثل أمام موسى وقال: «لنمض ونمتلك الأرض لأننا قادرون حقا على ذلك».","13:31":"فعارضه الرجال الذين كانوا معه وقالوا: «لا نقدر أن نقاوم سكانها لأنهم أقوى منا».","13:32":"وبذلك أشاعوا الذعر بين الإسرائيليين من البلاد التي تجسسوها قائلين: «ستفترسنا الأرض التي تجسسناها، وجميع من شاهدناهم من سكانها عمالقة.","13:33":"فقد رأينا هناك الجبابرة بني عناق، فبدونا في أعين أنفسنا كالجراد، وكذلك كنا في عيونهم».","14:1":"فرفع الشعب كله صوته وبكى في تلك الليلة،","14:2":"وتذمر على موسى وهرون، وقالوا: «ليتنا متنا في ديار مصر، أو ليتنا متنا في الصحراء.","14:3":"لماذا أحضرنا الرب إلى هذه الأرض لنهلك بحد السيف، وتؤخذ نساؤنا وأطفالنا سبايا؟ أليس من الأفضل لنا أن نرجع إلى مصر؟»","14:4":"وقال بعضهم لبعض: «لننتخب لنا قائدا ونرجع إلى مصر».","14:5":"فخر موسى وهرون على وجهيهما أمام جميع شعب إسرائيل،","14:6":"ومزق يشوع بن نون وكالب بن يفنة ثيابهما، وهما ممن تجسسوا الأرض،","14:7":"وقالا لكل الشعب: «إن الأرض التي اجتزنا فيها هي أرض خيرات عظيمة جدا.","14:8":"فإن رضي عنا الرب يدخلنا إليها ويهبها لنا، أرضا تفيض لبنا وعسلا.","14:9":"إنما لا تتمردوا على الرب ولا تجزعوا من شعب الأرض، لأننا سنبتلعهم كالخبز، فقد تلاشى ظل الحماية عنهم، والرب معنا فلا ترهبوهم».","14:10":"ولكن الشعب طالب برجمهما بالحجارة. غير أن مجد الرب ظهر في خيمة الاجتماع على مرأى منهم جميعا.","14:11":"وقال الرب لموسى: «إلى متى يمعن هذا الشعب في إهانتي، وإلى متى لا يصدقونني على الرغم من معجزاتي التي أجريتها في وسطهم؟","14:12":"سأبيدهم بالوبأ، وأجعلك شعبا أكبر وأعظم منهم».","14:13":"فقال موسى للرب: «عندئذ يسمع المصريون، الذين أخرجت هذا الشعب من بينهم بقدرتك، بهذا","14:14":"ويخبرون به أهل هذه الأرض، الذين قد سمعوا يارب أنك قائم في وسط هذا الشعب، وأنك قد ظهرت لهم وجها لوجه تظللهم بحمايتك، وتسير أمامهم في عمود سحاب نهارا وفي عمود نار ليلا.","14:15":"فإن أهلكت هذا الشعب دفعة واحدة، فإن الأمم التي سمعت بخبرك تقول","14:16":"إنك قد عجزت عن أن تدخل هذا الشعب إلى الأرض التي وعدتهم بها، فأهلكتهم في الصحراء.","14:17":"والآن لتتعظم قدرة سيدي كما نطقت قائلا:","14:18":"الرب طويل الأناة، وافر الرحمة، يغفر الذنب والسيئة. لكنه لا يبريء، بل يفتقد ذنب الآباء في الأبناء إلى الجيل الثالث والرابع.","14:19":"فاصفح عن ذنب هذا الشعب بحسب نعمتك، واغفر له كما غفرت ذنوبه من مصر إلى ههنا».","14:20":"فأجاب الرب: «قد صفحت بحسب قولك.","14:21":"ولكن كما أنا حقا حي، وكما أن مجد الرب حقا يملأ الأرض،","14:22":"فإن جميع الرجال الذين عاينوا مجدي ومعجزاتي التي أجريتها في مصر وفي الصحراء، وجربوني عشر مرات من غير أن يطيعوا قولي،","14:23":"لن يروا الأرض التي وعدت بها آباءهم. جميع الذين استخفوا بي، لن يشاهدوها.","14:24":"ولكن لأن في عبدي كالب روحا مختلفة، وقد تبعني بكل قلبه، فسأدخله إلى الأرض التي ذهب إليها، وسيرثها نسله من بعده.","14:25":"وبما أن العمالقة والكنعانيين ساكنون في الوديان، فارجعوا غدا إلى الصحراء في اتجاه البحر الأحمر».","14:26":"قال الرب لموسى وهرون:","14:27":"«إلى متى أصفح عن هذه الجماعة الشريرة المتذمرة علي؟ لقد سمعت تذمرهم علي،","14:28":"فقل لهم: حي أنا يقول الرب، لأنزلن بكم كل ما تكلمتم به في مسمعي.","14:29":"إذ تتساقط جثثكم في هذه الصحراء، من ابن عشرين سنة فما فوق ممن تم إحصاؤهم وتذمروا علي.","14:30":"لن تدخلوا الأرض التي وعدت رافعا يدي بقسم أن أسكنكم فيها، ما عدا كالب بن يفنة ويشوع بن نون.","14:31":"غير أني سأدخل إليها أولادكم الذين ادعيتم أنهم يصبحون أسرى، فيتمتعون بالأرض التي احتقرتموها.","14:32":"أما أنتم فإن جثثكم تتساقط في هذا القفر،","14:33":"ويبقى بنوكم في الصحراء أربعين سنة، تعانون من فجوركم، حتى تبلى جثثكم فيها.","14:34":"وتحملون أوزاركم أربعين سنة. كل يوم بسنة، على عدد الأيام الأربعين التي تجسستم فيها الأرض، فتدركون عاقبة ابتعادي عنكم.","14:35":"أنا الرب قد تكلمت، وهذا ما سأعاقب به هذه الجماعة الشريرة المتآمرة علي: في هذه الصحراء يفنون ويموتون».","14:36":"أما الجواسيس الذين أرسلهم موسى لاستكشاف الأرض، فرجعوا فأثاروا عليه الشعب بما روجوه من أخبار سيئة عن الأرض،","14:37":"فقد أماتهم الرب بالوبأ عقابا لهم","14:38":"ولم يعش منهم إلا يشوع بن نون وكالب بن يفنة.","14:39":"ولما أبلغ موسى هذا الكلام إلى جميع بني إسرائيل بكوا جدا.","14:40":"وفي الصباح الباكر صعدوا إلى رأس الجبل قائلين: «ها نحن قد أخطأنا، فلنمض إلى المكان الذي وعدنا به الرب».","14:41":"فقال موسى: «لماذا تعصون أمر الرب؟ إن عملكم هذا لن يفلح.","14:42":"لا تنطلقوا لئلا تنهزموا أمام أعدائكم، لأن الرب ليس في وسطكم،","14:43":"فالعمالقة والكنعانيون متربصون بكم هناك فتهلكون بحد السيف، لأنكم قد ارتددتم عن الرب ولن يكون الرب معكم».","14:44":"لكنهم، في غطرستهم، ارتقوا إلى قمة الجبل، غير أن تابوت عهد الرب وموسى لم يبرحا من وسط المخيم.","14:45":"فانقض عليهم العمالقة والكنعانيون المقيمون في ذلك الجبل، وهاجموهم وتعقبوهم إلى «حرمة».","15:1":"وقال الرب لموسى:","15:2":"«أوص بني إسرائيل وقل لهم: متى استوطنتم الأرض التي أنا واهبها لكم مسكنا،","15:3":"وقدمتم لي قربان محرقة أو ذبيحة وفاء لنذر، أو تقدمة طوعية أو قرابين في أعيادكم للحظوة برضى الرب ومسرته، من البقر والغنم.","15:4":"فليرفقها المقرب بتقدمة عشر من الدقيق المعجون بربع الهين (نحو لتر) من الزيت،","15:5":"وسكيب خمر مقداره ربع الهين (نحو لتر)، يصعده مع المحرقة أو الذبيحة للحمل الواحد.","15:6":"أما مع الكبش فليقرب تقدمة عشرين من الدقيق معجونين بثلث الهين (بنحو لتر وثلث اللتر) من الزيت","15:7":"وسكيب خمر مقداره ثلث الهين (نحو لتر وثلث اللتر)، يصعدها للحظوة برضى الرب ومسرته.","15:8":"وإذا قربت ثورا محرقة أو ذبيحة وفاء لنذر أو ذبيحة سلامة للرب،","15:9":"فأصعد مع الثور تقدمة ثلاثة أعشار من الدقيق معجونة بنصف الهين (بنحو لترين) من الزيت.","15:10":"وسكيب خمر مقداره نصف الهين (نحو لترين)، ليكون وقود رضى ومسرة للرب.","15:11":"هذا ما يقدم للثور الواحد، أو للكبش الواحد، أو للحمل أو للتيس.","15:12":"هكذا تفعلون بكل واحد منها على حسب أعدادها.","15:13":"ويمارس كل مواطن إسرائيلي هذه الشعائر على هذا المثال عندما يقدم محرقة لتكون رائحة سرور للرب.","15:14":"وإذا قرب غريب مقيم في وسطكم، أو نازل في دياركم على مدى أجيالكم محرقة رائحة سرور للرب، فليصنع كما تصنعون.","15:15":"فهذه فريضة دائمة لكم، وللغريب النازل عندكم على مدى أجيالكم، فتكونون على حد سواء أمام الرب.","15:16":"فتكون لكم وللغريب النازل عندكم شريعة واحدة وحكم واحد».","15:17":"وقال الرب لموسى:","15:18":"«أوص شعب إسرائيل وقل لهم: متى دخلتم الأرض التي أنا آخذكم إليها،","15:19":"وأكلتم من غلتها، فأصعدوا لي تقدمة منها.","15:20":"من أول عجينكم تقدمون قرصا قربانا، كقربان البيدر هكذا تقدمونه.","15:21":"إذ يتوجب عليكم، جيلا بعد جيل، أن تقدموا قربانا لي من أول عجينكم.","15:22":"وإذا سهوتم ولم تنفذوا جميع هذه الوصايا التي أبلغتها لموسى،","15:23":"والتي أمرتكم بممارستها على مدى أجيالكم، منذ أن أصدرتها إليكم على لسان موسى،","15:24":"وإن حدث هذا سهوا وعن غير علم الجماعة، فعلى كل الجماعة أن تقرب ثورا محرقة رائحة سرور للرب مع تقدمة من الدقيق وسكيبه من الخمر طبقا للشعائر، وتيسا واحدا ذبيحة خطيئة.","15:25":"فيكفر الكاهن عن جميع شعب إسرائيل، فأصفح عنهم، لأن الأمر صدر سهوا عنهم.","15:26":"فأصفح عن الشعب كله، والغريب المقيم بينكم، لأن الأمر صدر سهوا عن الشعب جميعه.","15:27":"وإن أخطأت نفس واحدة سهوا، فلتقرب عنزة حولية ذبيحة خطيئة.","15:28":"فيكفر الكاهن عن النفس التي سهت فأخطأت أمامي فأصفح عنها عندما يتم التكفير عنها.","15:29":"وتكون هذه شريعة واحدة تطبق على كل من أخطأ سهوا سواء كان مواطنا أم غريبا نازلا بينكم.","15:30":"أما إن تعمد أحد الخطأ، سواء كان من الإسرائيليين أم من الغرباء، فهو يزدري بي ويجب أن يستأصل من بين شعبه،","15:31":"لأنه احتقر كلامي ونقض وصيتي، لهذا يستأصل متحملا عقاب ذنبه».","15:32":"وفي أثناء إقامة بني إسرائيل في الصحراء، وجدوا رجلا يجمع حطبا في يوم السبت،","15:33":"فاقتادوه إلى موسى وهرون وبقية الجماعة،","15:34":"وزجوه في السجن لأنه لم يكن واضحا بعد ما يتوجب عليهم أن يفعلوا به.","15:35":"فقال الرب لموسى: «لترجمه الجماعة كلها بالحجارة خارج المخيم، لأن عقابه القتل حتما».","15:36":"فأخذه الشعب إلى خارج المخيم ورجموه بالحجارة حتى مات، كما أمر الرب موسى.","15:37":"وقال الرب لموسى:","15:38":"«أوص شعب إسرائيل وقل لهم: اصنعوا على مدى أجيالكم، أهدابا في أذيال ثيابكم وضعوا على هدب الذيل خيطا أزرق.","15:39":"فترون أهدابكم هذه وتذكرون كل وصاياي وتطيعونها، ولا تغوون أنفسكم باتباع شهوات قلوبكم وعيونكم.","15:40":"عندئذ تتذكرون أن تطيعوا جميع وصاياي وتتقدسوا لإلهكم.","15:41":"فأنا الرب إلهكم الذي أخرجكم من ديار مصر ليكون لكم إلها. أنا الرب إلهكم».","16:1":"وشرع قورح بن يصهار بن قهات بن لاوي، وداثان وأبيرام ابنا ألياب، وأون بن فالت من سبط رأوبين،","16:2":"يتآمرون على موسى، مع مئتين وخمسين من رؤساء جماعة بني إسرائيل، ذوي المكانة ممن تم تعيينهم في المجلس.","16:3":"هؤلاء تألبوا على موسى وهرون وقالوا: «حسبكما! إن كل الجماعة بأسرها مقدسة، وفي وسطها الرب. فما بالكما تترفعان على جماعة الرب؟»","16:4":"فلما سمع موسى هذا، أكب على وجهه،","16:5":"ثم قال لقورح وسائر جماعته: «غدا يعلن الرب من هو له، ومن هو المقدس فيقربه منه.","16:6":"ولكن ياقورح افعل هذا أنت وجماعتك: خذوا لكم مجامر،","16:7":"وضعوا فيها نارا وبخورا أمام الرب غدا. والرجل الذي يختاره الرب يكون هو المقدس، فحسبكم أيها اللاويون!»","16:8":"وأضاف موسى قائلا لقورح: «استمعوا يابني لاوي،","16:9":"ألم يكفكم أن إله إسرائيل قد أفرزكم من بين الشعب ليقربكم إليه لكي تخدموا مسكن الرب وتقفوا في حضرة الشعب كله لخدمته.","16:10":"فقربك مع بقية إخوتك من بني لاوي، حتى صرتم تطمعون في الكهنوت.","16:11":"إذن أنت وكل جماعتك قد تألبتم على الرب، لأنه من هو هرون حتى تتذمروا عليه؟»","16:12":"فأرسل موسى يستدعي داثان وأبيرام ابني أليآب، فردا: «لن نحضر!","16:13":"ألم يكفك أنك أخرجتنا من أرض تدر لبنا وعسلا لتهلكنا في الصحراء، ثم تترَأس علينا؟","16:14":"فأنت لم تقدنا إلى أرض تفيض خيرات، ولا أورثتنا حقولا وكروما. فمن تحاول أن تخدع؟ إننا لن نحضر!»","16:15":"فاحتدم غيظ موسى وقال للرب: «لا تقبل تقدمتهما، فأنا لم آخذ حتى حمارا واحدا منهما، ولم أسيء إلى أحد منهما».","16:16":"وقال موسى لقورح: «امثل أنت وجماعتك كلها أمام الرب غدا، وكذلك يحضر هرون أيضا.","16:17":"وليأخذ كل منكم مجمرته وضعوا فيها بخورا، وليقدم كل واحد مجمرته، فتكون مئتين وخمسين مجمرة، وكذلك خذ أنت وهرون، كل واحد مجمرته».","16:18":"فجاء كل واحد بمجمرته ووضعوا فيها نارا وبخورا، ومثلوا عند مدخل خيمة الاجتماع مع موسى وهرون.","16:19":"وحشد قورح عليهما كل الجماعة المتآمرة عند مدخل خيمة الاجتماع، فتراءى آنئذ مجد الرب للجماعة كلها.","16:20":"وقال الرب لموسى وهرون:","16:21":"«افترزا من بين هذه الجماعة لأني سأفنيهم في لحظة».","16:22":"فانطرحا على وجهيهما وابتهلا قائلين: «اللهم، ياإله أرواح جميع البشر، أتسخط على الجماعة كلها من أجل خطيئة رجل واحد؟»","16:23":"فقال الرب لموسى:","16:24":"«اطلب من الشعب أن يبتعدوا من حوالي خيام قورح وداثان وأبيرام».","16:25":"فذهب موسى إلى داثان وأبيرام، وتبعه شيوخ إسرائيل،","16:26":"وقال للجماعة كلها: «ابتعدوا عن خيام هؤلاء القوم الأشرار، ولا تلمسوا شيئا مما لهم لئلا تهلكوا من جراء خطاياهم».","16:27":"فابتعدوا من حوالي خيام قورح وداثان وأبيرام، وخرج داثان وأبيرام، ووقفا أمام خيمتيهما مع زوجاتهما وأولادهما صغارا وكبارا.","16:28":"فقال موسى: «بهذا تعرفون أن الرب قد أرسلني لأجري كل هذه الأعمال، وأنها ليست صادرة عن نفسي:","16:29":"إن مات هؤلاء موتا طبيعيا، أو ابتلوا بما يبتلى به الناس عادة، فلا يكون الرب قد أرسلني.","16:30":"ولكن إن أجرى الرب بدعة، وانشقت الأرض وابتلعتهم مع كل مالهم، ودفنوا في باطن الأرض أحياء، عندئذ تدركون أن هؤلاء القوم قد ازدروا بالرب».","16:31":"وحالما انتهى من كلامه انشقت الأرض تحتهم،","16:32":"وفتحت فاها وابتلعتهم مع بيوتهم، كما ابتلعت رجال قورح مع كل ما يملكون.","16:33":"فاختفوا هم وكل ما يملكون أحياء في باطن الأرض التي انطبقت عليهم، فبادوا من بين الجماعة.","16:34":"وهرب الإسرائيليون الذين حولهم من صوت صرخاتهم قائلين: «لئلا تبتلعنا الأرض».","16:35":"واندلعت نار من عند الرب فالتهمت المئتين والخمسين رجلا الذين قربوا البخور.","16:36":"ثم قال الرب لموسى:","16:37":"«اطلب من ألعازار بن هرون الكاهن أن يجمع المجامر من الحريق، وليذر ما فيها من جمر فإنها قد تقدست.","16:38":"واطرقوا مجامر هؤلاء الذين أخطأوا في حق نفوسهم صفائح، لتكون غشاء للمذبح، لأنهم قدموها في حضرة الرب فتقدست، فتكون عبرة لبني إسرائيل».","16:39":"فجمع ألعازار الكاهن مجامر النحاس التي قربها المحترقون، فطرقت غشاء للمذبح،","16:40":"عبرة لبني إسرائيل لكي لا يدنو أحد من غير نسل هرون ليبخر في حضرة الرب، فيصيبه ما أصاب قورح وجماعته، كما كلم الرب موسى.","16:41":"وفي اليوم الثاني تذمر جميع بني إسرائيل على موسى وهرون قائلين: «لقد قتلتما شعب الرب».","16:42":"فلما اجتمعت الجماعة على موسى وهرون مضيا إلى خيمة الاجتماع، وإذا بالسحابة قد غطتها ومجد الرب قد تراءى.","16:43":"فأقبل موسى وهرون إلى أمام خيمة الاجتماع.","16:44":"فقال الرب لموسى:","16:45":"«اخرجا من بين هذه الجماعة لأنني سأفنيهم في لحظة». فخرا على وجهيهما","16:46":"ثم قال موسى لهرون: «خذ المجمرة وضع فيها نارا من على المذبح، وأيضا بخورا، وأسرع إلى الجماعة لتكفر عنهم، لأن الغضب المحتدم قد صدر عن الرب وتفشى فيهم الوبأ».","16:47":"فنفذ هرون أمر موسى، وأسرع إلى وسط الجماعة، وإذا بالوبأ قد ابتدأ يتفشى فيهم، فوضع البخور وكفر عن الشعب.","16:48":"ووقف هرون بين الموتى والأحياء، فتوقف الوبأ.","16:49":"فكان الذين هلكوا بالوبإ أربعة عشر ألفا وسبع مئة، عدا الذين ماتوا بسبب قورح.","16:50":"ثم رجع هرون إلى موسى عند مدخل خيمة الاجتماع وقد توقف سريان الوبإ.","17:1":"وقال الرب لموسى:","17:2":"«كلم بني إسرائيل، وخذ منهم اثنتي عشرة عصا، واحدة من كل رئيس سبط من أسباط آبائهم، واحفر اسم كل واحد منهم على عصاه.","17:3":"واحفر اسم هرون على عصا لاوي، لأن لرئيس بيت آبائهم عصا واحدة.","17:4":"وضع العصي في خيمة الاجتماع أمام الشهادة حيث أجتمع بكم.","17:5":"فالرجل الذي أختاره تورق عصاه، وبذلك أضع حدا لتذمرات بني إسرائيل التي ترتفع ضدكما».","17:6":"فأبلغ موسى ذلك بني إسرائيل، فأعطاه كل واحد من رؤسائهم عصا بحسب أسباطهم فكانت اثنتي عشرة عصا. وكانت عصا هرون من بين عصيهم.","17:7":"فوضع موسى العصي أمام الرب في خيمة الشهادة.","17:8":"وفي اليوم التالي دخل موسى إلى خيمة الشهادة فوجد أن عصا هرون التي تمثل سبط لاوي قد أورقت، إذ أخرجت فروخا وأزهرت وأثمرت لوزا ناضجا.","17:9":"فأخرج موسى جميع العصي من حضرة الرب ليتفحصها بنو إسرائيل كلهم، فأخذ كل واحد عصاه.","17:10":"وقال الرب لموسى: «رد عصا هرون إلى أمام الشهادة واحفظها لتكون عبرة للمتمردين، فتكف تذمراتهم عني لئلا يهلكوا».","17:11":"ففعل موسى بمقتضى أمر الرب.","17:12":"وقال بنو إسرائيل لموسى: «إننا انقرضنا وهلكنا جميعا،","17:13":"لأن كل من اقترب إلى مسكن الرب يموت. ترى أنفنى كلنا؟»","18:1":"وقال الرب لهرون: «أنت وأبناؤك وبيت أبيك مسئولون عما يصيب المقدس من تدنيس، وأنت وأبناؤك معك تحملون مسئولية ما يرتكب في حق الكهنوت.","18:2":"واستعن بإخوتك من سبط لاوي، سبط أبيك، فينضموا إليك ويؤازروك أنت وأبناءك حين تقومون بالخدمة أمام خيمة الشهادة،","18:3":"فيقومون على خدمتك، وعلى خدمة خيمة الاجتماع. ولكن إياهم الاقتراب من أواني المقدس ومن المذبح، لئلا يموتوا جميعا وأنتم معهم.","18:4":"لينضموا إليك قائمين بخدمة الخيمة وكل ما يناط بهم من واجبات للعناية بها. ولكن لا يقترب منها من ليس منكم،","18:5":"فأنتم الكهنة الذين تقومون على خدمة المقدس والمذبح، لئلا ينصب السخط على بني إسرائيل.","18:6":"فقد اخترت إخوتكم اللاويين من بين الإسرائيليين ليكونوا لكم عطية من الرب، ليعتنوا بخدمة خيمة الاجتماع.","18:7":"أما أنت، وأبناؤك معك فقط، فتقومون بخدمة الكهنوت في جميع ما للمذبح وما هو وراء الحجاب، فأنا قد أعطيتكم خدمة الكهنوت هبة. وكل غريب يقترب من المقدس يقتل».","18:8":"وقال الرب لهرون: «ها أنا قد وليتك القيام بخدمة قرابيني. وكل التقدمات المقدسة التي يحضرها بنو إسرائيل لي، أمنحك إياها أنت وبنيك لتكون لكم نصيبا فريضة دائمة.","18:9":"فيكون من نصيبكم قرابين قدس الأقداس، إلا ما تحرقونه منها على المذبح؛ فيكون لكم من تقدمات قدس الأقداس التي يحضرونها لي، سواء كانت تقدمات دقيق أم ذبائح خطاياهم أم ذبائح آثامهم. هذه تكون نصيبا لك ولأبنائك.","18:10":"وعلى كل ذكر منكم أن يأكلها في مكان مقدس لأنها أصبحت مقدسة","18:11":"وأما ما ترجحه من عطايا بني إسرائيل فإنني أهبه لك ولأبنائك وبناتك فريضة دائمة، ولا يأكل منها من أهل بيتك إلا من كان طاهرا.","18:12":"وأعطيك أيضا باكورة غلات أفضل زيت الزيتون والخمر والحنطة التي يقدمونها للرب،","18:13":"فتكون لك أبكار غلات أرضهم التي يقدمونها للرب، فيأكل منها كل طاهر من أهل بيتك.","18:14":"كل ما هو منذور للرب في إسرائيل يكون لك.","18:15":"وكذلك كل بكر فاتح رحم من الناس والبهائم يقدمونه للرب يكون لك، ما عدا بكر الإنسان وبكر البهيمة النجسة فإنك تقبل فداءهما.","18:16":"وفداء الناس من ابن شهر، حسب تقويمك، خمسة شواقل (نحو ستين جراما) من الفضة وفقا للوزن المعتمد في القدس،","18:17":"لكن لا تقبل فداء بكر البقر أو الضأن أو المعز. إنه مفرز للرب. بل ترش دمه على المذبح، وتحرق شحمه وقودا رائحة رضى ومسرة للرب.","18:18":"أما لحمه فيكون لك نصيبا كصدر الترجيح والساق اليمنى.","18:19":"وهكذا أعطيك أنت وأبناءك وبناتك، حقا أبديا، جميع تقدمات الأقداس التي يقربها بنو إسرائيل للرب، فيكون هذا ميثاق ملح أبديا أمام الرب، لك ولنسلك أيضا».","18:20":"وقال الرب لهرون: «لا يكون لك ميراث في أرضهم ولا نصيب بينهم، لأنني أنا نصيبك وميراثك في وسط بني إسرائيل.","18:21":"أما اللاويون فقد وهبتهم كل عشر في إسرائيل، لقاء عملهم الذي يقومون به في خدمة خيمة الاجتماع.","18:22":"وعلى الإسرائيليين، منذ الآن، أن لا يقتربوا إلى خيمة الاجتماع، وإلا تحملوا نتائج خطيئتهم فيموتون.","18:23":"فاللاويون وحدهم يقومون بخدمة خيمة الاجتماع، ويتحملون مسئولية خطئهم، فتكون هذه لكم فريضة دائمة جيلا بعد جيل. ولا يكون للاويين نصيب من الأملاك في وسط إسرائيل.","18:24":"إن العشور التي يقدمها الإسرائيليون للرب قد وهبتها للاويين نصيبا، لهذا قلت لهم، لا يرثون نصيبا في وسط إسرائيل».","18:25":"وقال الرب لموسى:","18:26":"«أوص اللاويين وقل لهم: متى أخذتم من الإسرائيليين العشر الذي جعلته نصيبا لكم، تقدمون منه عشره للرب.","18:27":"فيحسب تقدمتكم مثل الحنطة من البيدر أو تقدمة عصير الكرمة.","18:28":"وهكذا تقدمون أنتم أيضا تقدمة للرب من جميع عشوركم التي تأخذونها من بني إسرائيل، وما تقربونه للرب، تعطونه لهرون الكاهن.","18:29":"وعليكم أن تحضروا للرب أفضل جزء وأقدسه مما أعطي لكم.","18:30":"وقل لهم: حين تقدمون من أفضل عطاياكم فإنها تحسب لكم مثل محصول البيدر ونتاج المعصرة.","18:31":"وتأكلونه في كل مكان أنتم وأهل بيوتكم، لأنه أجرة لكم لقاء خدمتكم في خيمة الاجتماع.","18:32":"ولدى تقديم خير جزء منها لا تتحملون وزرا بسببها. أما أقداس بني إسرائيل فلا تدنسوها لئلا تموتوا».","19:1":"وقال الرب لموسى وهرون:","19:2":"«هذه هي متطلبات الشريعة التي آمر بها: قل لبني إسرائيل أن يأتوك ببقرة حمراء سليمة خالية من كل عيب، لم يعلها نير،","19:3":"فتعطونها لألعازار الكاهن، ليأخذها إلى خارج المخيم وتذبح أمامه.","19:4":"ويغمس الكاهن إصبعه بدمها ويرش منه نحو وجه خيمة الاجتماع سبع مرات.","19:5":"وتحرق البقرة بجلدها ولحمها ودمها مع فرثها على مشهد منه،","19:6":"ثم يأخذ خشب أرز وزوفا، وخيطا أحمر، ويطرحها في وسط النيران.","19:7":"ثم يغسل الكاهن ثيابه ويستحم بماء، وبعد ذلك يدخل المخيم، ويظل الكاهن نجسا إلى المساء.","19:8":"ويغسل الرجل الذي أحرق البقرة ثيابه بماء ويستحم، ويظل أيضا نجسا إلى المساء.","19:9":"ويجمع رجل طاهر رماد البقرة ويلقيه خارج المخيم في موضع طاهر، فيظل محفوظا لجماعة إسرائيل لاستخدامه في ماء التطهير. إنها ذبيحة خطيئة.","19:10":"وعلى من جمع رماد البقرة أن يغسل ثيابه ويظل نجسا إلى المساء، فتكون هذه فريضة دائمة لبني إسرائيل وللغريب المقيم في وسطهم.","19:11":"من لمس جثمان إنسان ميت يبقى نجسا سبعة أيام،","19:12":"وعليه أن يتطهر بماء التطهير في اليوم الثالث، وفي اليوم السابع يصبح طاهرا. وإن لم يتطهر في اليوم الثالث، فلا يكون طاهرا في اليوم السابع.","19:13":"كل من لمس جثمان إنسان ميت ولم يتطهر، ينجس مسكن الرب، ويجب استئصاله من الشعب لأنه نجس، إذ إن ماء التطهير لم يرش عليه.","19:14":"أما شريعة من مات في خيمة، فإن كل من دخل الخيمة وكل من كان فيها، يكون نجسا سبعة أيام.","19:15":"وكل إناء مفتوح، لا غطاء عليه، أو غير محكم السد، يصبح نجسا.","19:16":"وكل من لمس على وجه الصحراء قتيلا بسيف أو ميتا، أو عظم إنسان أو قبرا، يكون نجسا سبعة أيام.","19:17":"فيأخذون للنجس من غبار حريق ذبيحة الخطيئة، ويصب عليه من ماء نبع جار في إناء.","19:18":"ويأخذ رجل طاهر أغصان الزوفا ويغمسها في الماء، ويرشه على الخيمة وعلى جميع الأمتعة، وعلى كل من كان حاضرا هناك، وعلى الذي لمس العظم أو القتيل أو الميت أو القبر.","19:19":"ثم يرش الطاهر ماء التطهير على النجس في اليوم الثالث واليوم السابع، ويطهره في اليوم السابع. وعلى المتطهر أن يغسل ثيابه ويستحم بماء فيصبح طاهرا في المساء","19:20":"أما الذي يتنجس ولا يتطهر فيستأصل من بين الجماعة، لأنه نجس مقدس الرب، ولم يرش عليه ماء التطهير، فظل نجسا.","19:21":"وتكون هذه لكم فريضة دائمة. وعلى من رش ماء التطهير أن يغسل ثيابه. وكل من لمس ماء التطهير يكون نجسا إلى المساء.","19:22":"وأي شيء يلمسه النجس يصبح نجسا، وكل من يلمسه الشيء المتنجس يصبح نجسا إلى المساء».","20:1":"وفي الشهر الأول أقبل بنو إسرائيل على صحراء صين، وأقاموا في قادش حيث ماتت مريم ودفنت هناك.","20:2":"وإذ لم يتوافر ماء للشعب اجتمعوا على موسى وهرون،","20:3":"وخاصموا موسى قائلين له: «ليتنا هلكنا كإخوتنا الذين أهلكهم الرب.","20:4":"لماذا قدتما شعب الرب إلى هذه الصحراء، لكي نموت فيها نحن ومواشينا؟","20:5":"لماذا أخرجتمانا من مصر لتأتيا بنا إلى هذا المكان القاحل، حيث لا زرع فيه ولا تين ولا كرم ولا رمان ولا ماء للشرب؟»","20:6":"فافترق موسى وهرون عن الجماعة، وقدما إلى مدخل خيمة الاجتماع حيث انطرحا على وجهيهما، فتراءى لهما مجد الرب،","20:7":"وقال الرب لموسى:","20:8":"«خذ العصا، واجمع الشعب أنت وأخوك هرون وأمرا الصخرة على مشهد منهم أن تعطي ماءها، فتخرج لهم ماء من الصخرة فيشرب الشعب ومواشيهم».","20:9":"فأطاع موسى وأخذ العصا من أمام الرب،","20:10":"وجمع موسى وهرون الشعب عند الصخرة وقالا لهم: «اسمعوا أيها المتمردون، أعلينا أن نخرج لكم من هذه الصخرة ماء؟»","20:11":"ورفع موسى يده وضرب الصخرة بعصاه مرتين، فتفجر ماء غزير، فشربت الجماعة ومواشيها.","20:12":"فقال الرب لموسى وهرون: «من حيث أنكما لم تؤمنا بي حتى تقدساني على مرأى من بني إسرائيل فإنكما لن تدخلا هذا الشعب الأرض التي وهبتها لهم».","20:13":"فكان هذا ماء مريبة حيث خاصم الإسرائيليون الرب فأظهر قداسته أمامهم.","20:14":"وبعث موسى رسلا من قادش إلى ملك أدوم يقولون له: «هذا ما يقوله لك أخوك إسرائيل: قد بلغك ما أصابنا من مشقة،","20:15":"فقد انحدر آباؤنا إلى مصر فمكثنا فيها أياما كثيرة، فسامنا المصريون، نحن وآباءنا سوء العذاب،","20:16":"فتضرعنا إلى الرب فاستجاب لصوتنا، وأرسل ملاكا أخرجنا من مصر. وها نحن نازلون في مدينة قادش في طرف تخومك.","20:17":"فأذن لنا أن نمر في أرضك من غير أن ندوس في حقل أو كرم أو نشرب ماء بئر، بل نسير في الطريق العامة المخصصة للسفر. لا نميل يمينا أو شمالا حتى نتجاوز حدودك».","20:18":"فقال لهم ملك أدوم: «إياكم المرور بأرضي لئلا أجابهكم بالسيف».","20:19":"فأجابه بنو إسرائيل: «لن نسير إلا على طريق السفر، وإن استقينا نحن ومواشينا من مائك ندفع ثمنه. إننا لا نطلب أكثر من المرور راجلين».","20:20":"فقال: «لا تمروا». وعبأ ملك أدوم جيشا قويا وخرج للقاء إسرائيل.","20:21":"وأبى ملك أدوم أن يأذن للإسرائيليين باجتياز أراضيه. فتحولوا عنه.","20:22":"وارتحلوا جميعهم من قادش حتى أقبلوا على جبل هور.","20:23":"وقال الرب لموسى وهرون في جبل هور عند حدود أرض أدوم:","20:24":"«هرون لن يلبث أن يموت، لأنه لن يدخل الأرض التي وهبتها لبني إسرائيل، لأنكم عصيتم كلامي عند ماء مريبة».","20:25":"خذ هرون وألعازار ابنه واصعد إلى جبل هور،","20:26":"وانزع عن هرون ثيابه وألبسها ألعازار ابنه، لأن هناك يموت هرون».","20:27":"ففعل موسى كما أمر الرب، فصعدوا جميعا إلى الجبل على مرأى من الشعب كله،","20:28":"فنزع موسى ثياب هرون وألبسها ألعازار ابنه. ومات هرون هناك على قمة الجبل، ثم انحدر موسى وألعازار عن الجبل.","20:29":"وعندما علم الشعب أن هرون قد مات، ناحوا عليه ثلاثين يوما.","21:1":"وعندما سمع ملك عراد الكنعاني، المستوطن في النقب، أن الإسرائيليين قادمون على طريق أتاريم، حاربهم وأسر عددا منهم.","21:2":"فنذر الإسرائيليون للرب نذرا قائلين: «إن أظفرتنا بهؤلاء القوم، لنحرمن مدنهم».","21:3":"فاستجاب الرب لهم، وأظفرهم بالكنعانيين، فحرموهم ومدنهم، فدعي اسم المكان «حرمة».","21:4":"وارتحلوا من جبل هور عن طريق البحر الأحمر ليدوروا حول أرض أدوم فأعيت نفس الشعب في الطريق،","21:5":"وتذمروا على الله وعلى موسى قائلين: «لماذا أخرجتمانا من مصر لنموت في الصحراء، حيث لا خبز ولا ماء؟ وقد عافت أنفسنا الطعام التافه».","21:6":"فأطلق الرب على الشعب الحيات السامة، فلدغت الشعب، فمات منهم قوم كثيرون.","21:7":"فجاء الشعب إلى موسى قائلين: «لقد أخطأنا إذ تذمرنا على الرب وعليك، فابتهل إلى الرب ليخلصنا من الحيات». فصلى موسى من أجل الشعب،","21:8":"فقال الرب لموسى: «اصنع لك حية سامة وارفعها على عمود، لكي يلتفت إليها كل من تلدغه حية، فيحيا»","21:9":"فصنع موسى حية من نحاس وأقامها على عمود، فكان كل من لدغته حية، يلتفت إلى حية النحاس ويحيا.","21:10":"ثم انتقل بنو إسرائيل ونزلوا في أوبوت،","21:11":"ومنها ارتحلوا وحلوا في عيي عباريم، في الصحراء المقابلة لموآب في اتجاه الشرق.","21:12":"ثم ارتحلوا من هناك ونزلوا في وادي زارد،","21:13":"بعد ذلك انتقلوا من هناك وأقاموا إلى جانب أرنون في الصحراء، وراء حدود الأموريين، لأن أرنون هي الحد الفاصل ما بين بلاد موآب والأموريين.","21:14":"لذلك ورد في كتاب حروب الرب: «مدينة واهب في منطقة سوفة، وأودية نهر أرنون،","21:15":"ومصب الأودية الممتد نحو مدينة عار، والمستند إلى حدود موآب».","21:16":"ومن هناك مضوا نحو بئر، وهي البئر التي قال الرب عندها لموسى: «اجمع الشعب لأعطيهم ماء»","21:17":"حينئذ شدا الإسرائيليون بهذا النشيد: «ارتفع ياماء البئر!","21:18":"تغنوا بها، تغنوا بالبئر التي حفرها رؤساء. حفرها شرفاء الشعب بالصولجان والعصي». ثم انتقلوا من الصحراء إلى متانة.","21:19":"ومن متانة إلى نحليئيل ومن نحليئيل إلى باموت.","21:20":"ومن باموت إلى الجواء التي في صحراء موآب عند قمة الفسجة المشرفة على امتداد الصحراء.","21:21":"وبعث الإسرائيليون رسلا إلى سيحون ملك الأموريين قائلين:","21:22":"«دعنا نجتز في أرضك، فلا نميل إلى حقل ولا إلى كرم، ولا نشرب ماء بئر، بل نسير في الطريق العامة المخصصة للسفر حتى نعبر حدودك.","21:23":"فلم يأذن سيحون للإسرائيليين بالمرور في تخومه، بل حشد جيشه وخرج للقائهم إلى الصحراء، وحاربهم عند ياهص،","21:24":"فهزمه الإسرائيليون بحد السيف، واستولوا على بلاده من أرنون إلى يبوق حتى حدود العمونيين ولم يتجاوزوها لمناعتها.","21:25":"وامتلك الإسرائيليون كل مدن الأموريين، ومن جملتها حشبون وضواحيها وأقاموا فيها،","21:26":"لأن حشبون كانت عاصمة سيحون ملك الأموريين الذي كان قد حارب ملك موآب السابق واستولى على أراضيه كلها حتى أرنون.","21:27":"لهذا يقول الشعراء: «هيا إلى حشبون فتبنى، وتشيد مدينة سيحون.","21:28":"فقد اندلعت نار من حشبون، لهيب من مدينة سيحون، فالتهمت عار موآب، وأهلكت أهل مرتفعات أرنون.","21:29":"ويل لك ياموآب. هلكت ياأمة كموش. قد هرب أبناؤه وأصبحت بناته سبايا سيحون ملك الأموريين.","21:30":"لكن قد طوحنا بهم. هلكت حشبون إلى ديبون، دمرنا البلاد حتى نوفح التي تمتد إلى ميدبا».","21:31":"فأقام الإسرائيليون في بلاد الأموريين.","21:32":"وأرسل موسى ليستكشف منطقة يعزير، وما لبث بنو إسرائيل أن استولوا على قراها وطردوا منها الأموريين،","21:33":"ثم اتجهوا نحو طريق باشان. فهب عوج ملك باشان مع جميع قومه للقائهم في إذرعي ومحاربتهم.","21:34":"فقال الرب لموسى: «لا تخف منه لأنني قد دفعته ليدك مع جميع قومه وأرضه، فتفعل به ما فعلته بسيحون ملك الأموريين في حشبون».","21:35":"فقضوا عليه وعلى أبنائه وقومه حتى لم يبق منهم حي، وامتلكوا دياره.","22:1":"وارتحل الإسرائيليون ونزلوا في سهول موآب، شرقي الأردن مقابل أريحا.","22:2":"وإذ بلغ بالاق بن صفور ملك موآب جميع ما أنزله الإسرائيليون بالأموريين،","22:3":"اعتراه الفزع لكثرة عددهم، وملأ الخوف قلب شعبه من الإسرائيليين.","22:4":"فقال بالاق لشيوخ مديان: «إن هذا الجمهور قادر على لحس كل ما حولنا كما يلحس الثور عشب الحقل».","22:5":"ثم بعث برسل يستدعي بلعام بن بعور، المقيم في موطنه في فتور، الواقعة على نهر الفرات قائلا: «ها قد خرج شعب من مصر يغشي وجه الأرض بكثرته، وهو منتشر أمامي.","22:6":"فتعال الآن والعن لي هذا الشعب لأنه أعظم مني، لعلي أتمكن من دحره وطرده من الأرض، لأني عرفت أن من تباركه يكون مباركا ومن تلعنه يكون ملعونا».","22:7":"فمضى شيوخ موآب وشيوخ مديان حاملين معهم حلوان العرافة، وأقبلوا على بلعام وأبلغوه كلام بالاق.","22:8":"فقال لهم: «بيتوا هنا الليلة، وغدا أرد عليكم جوابا كما يعلن لي الرب». فمكث رؤساء موآب عند بلعام.","22:9":"فتجلى الله لبلعام وسأله: «من هم هؤلاء الرجال الذين عندك؟»","22:10":"فأجاب: «لقد أرسل بالاق بن صفور ملك موآب إلي قائلا:","22:11":"ها قد خرج شعب من مصر يغشي وجه الأرض. فتعال الآن والعنه لي، لعلي أقدر على محاربته وطرده».","22:12":"فقال الله لبلعام: «لا تمض معهم ولا تلعن الشعب لأنه مبارك».","22:13":"فنهض بلعام في الصباح وقال لرؤساء بالاق: «انطلقوا إلى دياركم، لأن الرب أبى أن يأذن لي بالذهاب معكم».","22:14":"فانطلق رؤساء موآب وأبلغوا بالاق أن بلعام رفض أن يحضر معهم.","22:15":"فعاد بالاق وبعث أيضا عددا من الرؤساء أكبر، وعظماء أكثر من الرؤساء الأولين.","22:16":"فقدموا على بلعام وقالوا: «هذا ما يقوله لك بالاق بن صفور:","22:17":"لا تتقاعس عن المجيء إلي، لأنني سأبالغ في إكرامك، وكل ما تطلبه أفعله، فتعال الآن والعن هذا الشعب».","22:18":"فأجاب بلعام رسل بالاق: «لا يمكنني أن أعصى أمر الرب إلهي في أي عمل صغير أو كبير، ولو أغدق علي بالاق ملء قصره فضة وذهبا.","22:19":"فالآن، اقضوا هنا ليلتكم لأعلم بماذا يعود الرب فيوصيني به».","22:20":"فتراءى الله لبلعام ليلا وقال له: «إن جاء الرجال يستدعونك فقم وامض معهم، إنما لا تنطق إلا بما آمرك به فقط».","22:21":"فنهض بلعام صباحا وأسرج أتانه، وانطلق مع رؤساء موآب.","22:22":"فاحتدم غضب الله لأنه مضى معهم، فاعترضه ملاك الرب في الطريق ليقاومه وهو راكب على أتانه وغلاماه معه.","22:23":"فأبصرت الأتان ملاك الرب منتصبا في الطريق، وقد استل سيفه بيده، فحادت عن الطريق ومشت في الحقل. فضربها بلعام ليردها إلى الطريق.","22:24":"ثم وقف ملاك الرب في ممر للكروم يقوم على جانبيه حائطان.","22:25":"فلما شاهدت الأتان ملاك الرب زحمت جانب الحائط وضغطت رجل بلعام عليه، فضربها أيضا.","22:26":"ثم اجتاز به ملاك الرب ووقف في موضع ضيق، لا سبيل فيه للتحول يمنة أو يسرة.","22:27":"فلما رأت الأتان ملاك الرب ربضت تحت بلعام. فثار غضب بلعام وضرب الأتان بالقضيب.","22:28":"عندئذ أنطق الرب الأتان، فقالت لبلعام: «ماذا جنيت حتى ضربتني الآن ثلاث دفعات؟»","22:29":"فقال بلعام: «لأنك سخرت مني. لو كان في يدي سيف لكنت قد قتلتك».","22:30":"فأجابته الأتان: «ألست أنا أتانك التي ركبت عليها دائما إلى هذا اليوم؟ وهل عودتك أن أصنع بك هكذا؟» فقال: «لا».","22:31":"عندئذ كشف الرب عن عيني بلعام، فشاهد ملاك الرب منتصبا في الطريق وسيفه مسلول في يده، فخر على وجهه ساجدا.","22:32":"فقال له ملاك الرب: «لماذا ضربت الآن أتانك ثلاث مرات؟ فها أنا قد جئت لأعترضك، لأن طريقك ملتوية في نظري،","22:33":"فشاهدتني الأتان فحادت من أمامي ثلاث مرات. ولو لم تفعل لكنت قد قتلتك واستحييتها».","22:34":"فقال بلعام لملاك الرب: «لقد أخطأت، ولم أعلم أنك واقف لاعتراضي في الطريق. والآن إن ساء في عينيك فإني أرجع».","22:35":"فقال ملاك الرب لبلعام: «امض مع الرجال، ولكن عليك أن تنطق بما آمرك به فقط». فانطلق بلعام مع رؤساء بالاق.","22:36":"فلما بلغ بالاق أن بلعام قد قدم أسرع لاستقباله إلى مدينة موآب الواقعة على حدود أرنون القصية.","22:37":"فقال بالاق لبلعام: «ألم أبعث إليك أستدعيك؟ فلماذا لم تقدم علي؟ أحقا أعجز عن إكرامك؟»","22:38":"فأجاب بلعام: «ها أنا جئت إليك. أتظن أن في وسعي أن أتكلم الآن بما أريد؟ علي أن أنطق فقط بما يأمرني به الرب».","22:39":"فمضى بلعام مع بالاق حتى أقبلا إلى قرية حصوت.","22:40":"فذبح بالاق بقرا وغنما وأرسلها إلى بلعام ومن معه من الرؤساء.","22:41":"وفي الصباح التالي أخذ بالاق بلعام إلى مرتفعات بعل، فرأى من هناك بني إسرائيل كلهم.","23:1":"فقال بلعام لبالاق: «ابن لي هنا سبعة مذابح، وأعد لي هنا سبعة ثيران وسبعة كباش».","23:2":"ففعل بالاق كما طلب بلعام. وقرب بالاق وبلعام ثورا وكبشا على كل مذبح.","23:3":"ثم قال بلعام لبالاق: «قف هنا عند محرقاتك فأمضي أنا، لعل الرب يأتي للقائي، ومهما يعلن لي أبلغك به». ثم ارتقى بلعام رابية.","23:4":"فوافى الله بلعام. فقال بلعام: «قد أعددت سبعة مذابح وقربت ثورا وكبشا على كل مذبح».","23:5":"فحمل الرب بلعام رسالة وقال: «ارجع إلى بالاق وبلغه إياها».","23:6":"فعاد إليه، وإذا به مازال واقفا عند محرقاته، ومعه جميع رؤساء موآب،","23:7":"فنطق بنبوءته قائلا: «أتى بي بالاق ملك موآب من بلاد أرام من الجبال الشرقية، وقال: تعال العن لي يعقوب، واشتم لي إسرائيل.","23:8":"كيف ألعن من لم يلعنه الله؟ وكيف أشتم من لم يشتمه الرب؟","23:9":"ها أنا أراهم من قمم الصخور، ومن الآكام أبصرهم. هوذا شعب يسكن وحده. ولا يحسبون أنفسهم أمة من الأمم.","23:10":"من يقدر أن يحصي تراب يعقوب أو يعد ربع إسرائيل؟ لتمت نفسي موت الأبرار، ولتكن آخرتي كآخرتهم».","23:11":"فقال بالاق لبلعام: «ماذا فعلت بي؟ لقد استدعيتك لتشتم أعدائي، وها أنت تباركهم»","23:12":"فأجابه: «إنني أحرص أن لا أتكلم إلا بما يضعه الرب على فمي».","23:13":"فقال له بالاق: «تعال معي إلى موضع آخر فلا ترى منه إلا طرف مخيم الشعب فقط، والعنه لي من هناك».","23:14":"فأخذه إلى حقل صوفيم المشرف على رأس الفسجة وهناك شيد سبعة مذابح، وقرب بلعام ثورا وكبشا على كل مذبح.","23:15":"وقال لبالاق: «انتظرني هناك عند محرقاتك وأنا أمضي إلى هناك».","23:16":"فوافى الرب بلعام ولقنه رسالة وقال له: «ارجع إلى بالاق وبلغه إياها».","23:17":"فأقبل على بالاق، وإذا به منتظر عند محرقاته ومعه رؤساء موآب. فسأله بالاق: «ماذا تكلم به الرب؟»","23:18":"فضرب مثله قائلا: «انهض يابالاق واصغ، استمع إلي ياابن صفور","23:19":"ليس الله إنسانا فيكذب. ولا هو ابن آدم فيندم. هل يقول ولا يفعل أو يعد ولا يفي؟","23:20":"إني أمرت أن أبارك، وهو قد بارك ولا طاقة لي على رده.","23:21":"لم يشهد إثما في يعقوب، ولم ير مشقة في إسرائيل. الرب إلههم معهم، وهتاف للملك فيهم.","23:22":"الله أخرجهم من مصر، وقوتهم مثل قوة الثور الوحشي.","23:23":"فلا عيافة تضر يعقوب، ولا عرافة تؤثر في إسرائيل. منذ الآن يقال عن يعقوب وعن إسرائيل: «انظر ماذا فعل الله!»","23:24":"هوذا شعب يتحفز كلبوة وينهض كأسد. لا ينام حتى يلتهم فريسة ويلغ في دم قتلى».","23:25":"فقال بالاق لبلعام: «إذن لا تلعنه ولا تباركه!»","23:26":"فأجاب بلعام: «ألم أخبرك أنني لن أنطق إلا بما يأمرني به الرب؟»","23:27":"فقال بالاق: «دعني آخذك إلى موضع آخر، فعسى أن يحسن في عيني الله أن تلعن لي الشعب من هناك».","23:28":"فأخذ بالاق بلعام إلى قمة جبل فغور المشرف على امتداد الصحراء،","23:29":"فقال بلعام لبالاق: «ابن لي هنا سبعة مذابح. وجهز لي هنا سبعة ثيران وسبعة كباش».","23:30":"فلبى بالاق طلب بلعام، وقرب ثورا وكبشا على كل مذبح.","24:1":"ولما رأى بلعام أن الرب يسر بمباركة إسرائيل لم يمض كالمرتين السابقتين لملاقاة الرب، لكنه توجه بنظره نحو الصحراء،","24:2":"وهناك شاهد بني إسرائيل مخيمين حسب أسباطهم، فحل عليه روح الله،","24:3":"وتنبأ قائلا: «كلام بلعام بن بعور، كلام الرجل المفتوح العينين.","24:4":"كلام من يسمع أقوال الله والذي يشاهد رؤيا القدير. الذي ينطرح فتنفتح عيناه.","24:5":"ما أجمل خيامك يايعقوب، وما أبهى مساكنك ياإسرائيل!","24:6":"هي مثل أودية ممتدة، وكجنات على مجرى نهر، وكشجرات صبار غرسها الرب، ومثل أشجار الأرز النامية بجوار المياه.","24:7":"تجري مياه من مساقيه، ولزرعه يتوافر ماء غزير. يكون ملكه أعظم شأنا من أجاج وتتسامى مملكته.","24:8":"الله أخرجه من مصر، وقوته مثل الثور الوحشي. يفترس خصومه من الأمم، ويقضم عظامهم ويثخنهم بسهامه.","24:9":"يجثم كأسد، ويربض كلبوة. فمن يجرؤ على إثارته؟ من يباركك يكون مباركا، ومن يلعنك يكون ملعونا».","24:10":"فاستشاط بالاق غضبا على بلعام، وضرب كفا على كف قائلا له: «دعوتك لتشتم أعدائي، وها أنت قد باركتهم ثلاث مرات!","24:11":"والآن اغرب عن وجهي وامض إلى بيتك، فقد كان في عزمي إكرامك ولكن الرب شاء أن لا تحظى به».","24:12":"فأجابه بلعام: «ألم أقل لرسلك الذين بعثتهم إلي","24:13":"إنه ولو أغدق علي بالاق ملء قصره ذهبا وفضة فلن أعصي أمر الرب، فأصنع خيرا أو شرا من نفسي؟ فإن ما يعلنه لي الرب فإياه أبلغ.","24:14":"والآن أعود إلى شعبي، ولكن دعني أنبئك بما سينزله هذا الشعب بقومك في آخر الأيام».","24:15":"ثم تنبأ قائلا: «كلام بلعام بن بعور، كلام الرجل المفتوح العينين.","24:16":"كلام من يسمع أقوال الله، ويتلقى المعرفة من العلي، الذي يشاهد رؤيا القدير، الذي ينطرح فتنفتح عيناه.","24:17":"أراه ولكن ليس حاضرا، وأبصره ولكن ليس قريبا. يخرج نجم من يعقوب، ويظهر ملك من إسرائيل فيحطم طرفي موآب، ويهلك كل رجال الحرب.","24:18":"ويرث أرض أدوم، ويتملك ديار سعير. أما إسرائيل فيزداد قوة.","24:19":"ويبرز حاكم من يعقوب فيدمر ما تبقى من مدن (الأعداء)».","24:20":"ثم تطلع بلعام نحو مساكن أهل عماليق فتنبأ: «كان عماليق أول الشعوب، أما عاقبته فإلى الهلاك».","24:21":"ثم التفت نحو القينيين فأنبأ: «ليكن مسكنك منيعا، وعشك موضوعا في صخرة.","24:22":"وإنما ستدمرون عندما يطردكم الأشوريون».","24:23":"ثم تنبأ قائلا: «من له طاقة على العيش حين يجري الرب ذلك؟","24:24":"تقبل سفن من كتيم، وتخضع أشور وتذل عابر، فهما أيضا يهلكان».","24:25":"ثم رجع بلعام إلى دياره، وأما بالاق فمضى في سبيله.","25:1":"وأقام الإسرائيليون في شطيم، فشرع الرجال يرتكبون الزنى مع الموآبيات","25:2":"اللواتي أغوين الشعب لحضور ذبائح آلهتهن والأكل منها والسجود لها.","25:3":"فاشترك الإسرائيليون في عبادة بعل فغور. فاحتدم غضب الرب عليهم.","25:4":"فقال الرب لموسى: «خذ جميع قادة عبدة البعل واصلبهم، وعلقهم تحت وطأة حرارة الشمس أمام الرب، فترتد شدة غضبه عن بني إسرائيل».","25:5":"فقال موسى لقضاة إسرائيل: «اقتلوا كل واحد من قومكم من المتعلقين بعبادة بعل فغور».","25:6":"وإذ كان موسى وسائر جماعة إسرائيل يبكون عند مدخل خيمة الاجتماع، أقبل إسرائيلي وقدم إلى إخوته امرأة مديانية على مرأى منهم.","25:7":"فلما رأى فينحاس بن ألعازار بن هرون ذلك، هب من بين الجماعة، وتناول رمحا بيده،","25:8":"وتبع الإسرائيلي إلى الخيمة حيث طعنهما. فاخترق الرمح الرجل الإسرائيلي وبطن المرأة، فكف الوبأ عن بني إسرائيل.","25:9":"وكان عدد الذين ماتوا بالوبإ أربعة وعشرين ألفا.","25:10":"فقال الرب لموسى:","25:11":"«إن فينحاس بن ألعازار بن هرون الكاهن قد رد غضبي عن بني إسرائيل، إذ غار غيرتي في وسطهم، فلم أفن بني إسرائيل بغيرتي.","25:12":"لذلك قل له: هأنذا أقطع معه ميثاق سلام،","25:13":"فيكون له ولنسله من بعده ميثاق كهنوت أبدي، لأنه غار لله وكفر عن الإسرائيليين».","25:14":"وكان اسم الإسرائيلي الذي قتل مع المرأة المديانية زمري بن سالو، وهو أحد رؤساء عائلة من سبط شمعون.","25:15":"أما المرأة المديانية المقتولة فكان اسمها كزبي بنت صور الذي كان رئيس قبيلة من قبائل مديان.","25:16":"ثم قال الرب لموسى:","25:17":"«أسيئوا معاملة المديانيين وأهلكوهم،","25:18":"لأنهم ضايقوكم بمكايدهم التي احتالوا بها عليكم بشأن فغور، وأختهم كزبي ابنة رئيس لمديان، التي قتلت عندما تفشى الوبأ بسبب عبادة فغور».","26:1":"وبعد توقف الوبإ قال الرب لموسى وألعازار بن هرون الكاهن:","26:2":"«أحصيا كل جماعة إسرائيل، من ابن عشرين سنة فما فوق، من القادرين على التجند في جيش إسرائيل، حسب انتماء كل منهم لسبطه».","26:3":"فقال موسى وألعازار الكاهن للشعب في سهول موآب بقرب نهر الأردن مقابل أريحا:","26:4":"«أحصوا كل رجل من ابن عشرين سنة فما فوق، كما أمر الرب موسى». فكان هؤلاء هم الخارجون من ديار مصر.","26:5":"رأوبين بكر يعقوب، أما أبناؤه فهم: حنوك رأس عشيرة الحنوكيين، وفلو رأس عشيرة الفلويين.","26:6":"وحصرون رأس عشيرة الحصرونيين، وكرمي رأس عشيرة الكرميين.","26:7":"هذه العشائر المنحدرة من نسل رأوبين. وكان المحصون منهم ثلاثة وأربعين ألفا وسبع مئة وثلاثين.","26:8":"وأليآب بن فلو.","26:9":"أما أبناء أليآب فهم: نموئيل وداثان وأبيرام. وكان داثان وأبيرام من المنتخبين في المجلس وهما اللذان خاصما موسى وهرون مع بقية جماعة قورح حين تمردوا على الرب.","26:10":"فانشقت الأرض آنئذ وابتلعتهما مع قورح، حين أحرقت النار القوم البالغ عددهم مئتين وخمسين رجلا، فصاروا عبرة.","26:11":"غير أن أبناء قورح لم يهلكوا.","26:12":"أما أبناء شمعون فهم: نموئيل رأس عشيرة النموئيليين، ويامين رأس عشيرة اليامينيين، وياكين رأس عشيرة الياكينيين.","26:13":"وزارح رأس عشيرة الزارحيين. وشأول رأس عشيرة الشأوليين.","26:14":"هذه هي العشائر المنحدرة من نسل شمعون، وعدد المحصين منهم اثنان وعشرون ألفا ومئتان.","26:15":"أما أبناء جاد فهم: صفون رأس عشيرة الصفونيين، وحجي رأس عشيرة الحجيين، وشوني رأس عشيرة الشونيين،","26:16":"وأزني رأس عشيرة الأزنيين، وعيري رأس عشيرة العيريين،","26:17":"وأرود رأس عشيرة الأروديين، وأرئيلي رأس عشيرة الأرئيليين.","26:18":"هذه هي العشائر المنحدرة من نسل جاد. وكان المحصون منهم أربعين ألفا وخمس مئة.","26:19":"أما ابنا يهوذا عير وأونان فقد ماتا في أرض كنعان من غير عقب.","26:20":"والذين أعقبوا نسلا من أبناء يهوذا هم: شيلة رأس عشيرة الشيليين، وفارص رأس عشيرة الفارصيين، وزارح رأس عشيرة الزارحيين.","26:21":"وأبناء فارص: حصرون رأس عشيرة الحصرونيين، وحامول رأس عشيرة الحاموليين.","26:22":"هذه هي العشائر المنحدرة من نسل يهوذا. وكان المحصون منهم ستة وسبعين ألفا وخمس مئة.","26:23":"أما أبناء يساكر فهم: تولاع رأس عشيرة التولاعيين، وفوة رأس عشيرة الفويين،","26:24":"وياشوب رأس عشيرة الياشوبيين، وشمرون رأس عشيرة الشمرونيين.","26:25":"هذه هي العشائر المنحدرة من نسل يساكر. وكان المحصون منهم أربعة وستين ألفا وثلاث مئة.","26:26":"أما أبناء زبولون فهم: سارد رأس عشيرة السارديين، وإيلون رأس عشيرة الإيلونيين وياحلئيل رأس عشيرة الياحلئيليين.","26:27":"هذه هي العشائر المنحدرة من نسل زبولون. وكان المحصون منهم ستين ألفا وخمس مئة.","26:28":"أما ابنا يوسف فهما: منسى وأفرايم.","26:29":"ونسل منسى ماكير رأس عشيرة الماكيريين، وأنجب ماكير جلعاد، فكان جلعاد رأس عشيرة الجلعاديين.","26:30":"وهؤلاء هم أبناء جلعاد: إيعزر رأس عشيرة الإيعزريين وحالق رأس عشيرة الحالقيين،","26:31":"وأسريئيل رأس عشيرة الأسريئيليين، وشكم رأس عشيرة الشكميين،","26:32":"وشميداع رأس عشيرة الشميداعيين، وحافر رأس عشيرة الحافريين.","26:33":"وأنجب حافر صلفحاد الذي لم ينجب سوى بنات هن: محلة ونوعة وحجلة وملكة وترصة.","26:34":"هذه هي العشائر المنحدرة من نسل منسى. وكان المحصون منهم اثنين وخمسين ألفا وسبع مئة.","26:35":"أما أبناء أفرايم فهم: شوتالح رأس عشيرة الشوتالحيين، وباكر رأس عشيرة الباكريين، وتاحن رأس عشيرة التاحنيين.","26:36":"وأنجب شوتالح عيران رأس عشيرة العيرانيين.","26:37":"هذه هي العشائر المنحدرة من نسل أفرايم. وكان المحصون منهم اثنين وثلاثين ألفا وخمس مئة، وجميع هذه العشائر من نسل يوسف.","26:38":"أما أبناء بنيامين فهم: بالع رأس عشيرة البالعيين، وأشبيل رأس عشيرة الأشبيليين، وأحيرام رأس عشيرة الأحيراميين.","26:39":"وشفوفام رأس عشيرة الشفوفاميين، وحوفام رأس عشيرة الحوفاميين.","26:40":"وأنجب بالع أرد ونعمان، فكان أرد رأس عشيرة الأرديين، ونعمان رأس عشيرة النعمانيين.","26:41":"هذه هي العشائر المنحدرة من نسل بنيامين، وكان المحصون منهم خمسة وأربعين ألفا وست مئة.","26:42":"أما ابن دان فهو: شوحام رأس عشيرة الشوحاميين، وهي العشيرة المنحدرة من نسل دان.","26:43":"وكان المحصون من عشيرة الشوحاميين أربعة وستين ألفا وأربع مئة.","26:44":"أما أبناء أشير فهم: يمنة رأس عشيرة اليمنيين، ويشوي رأس عشيرة اليشويين، وبريعة رأس عشيرة البريعيين.","26:45":"وأنجب بريعة حابر رأس عشيرة الحابريين، وملكيئيل رأس عشيرة الملكيئيليين.","26:46":"وكان لأشير ابنة اسمها سارح.","26:47":"هذه هي العشائر المنحدرة من نسل أشير، وكان المحصون منهم ثلاثة وخمسين ألفا وأربع مئة.","26:48":"أما أبناء نفتالي فهم: ياحصئيل رأس عشيرة الياحصئيليين، وجوني رأس عشيرة الجونيين.","26:49":"ويصر رأس عشيرة اليصريين، وشليم رأس عشيرة الشليميين.","26:50":"هذه هي العشائر المنحدرة من نسل نفتالي، وكان المحصون منهم خمسة وأربعين ألفا وأربع مئة.","26:51":"فكان جملة المحصين من بني إسرائيل ست مئة ألف وألفا وسبع مئة وثلاثين.","26:52":"ثم قال الرب لموسى:","26:53":"«قسم الأرض بين الأسباط وفقا لنسبة عدد أفراد كل سبط،","26:54":"فالسبط الكبير أعطه نصيبا أكبر، والسبط الصغير أعطه نصيبا أقل. أعط كل سبط حسب أعداد أفراده المحصين،","26:55":"على أن توزع الأرض بالقرعة، فيملكون الأرض حسب أسماء آباء أسباطهم،","26:56":"فتوزع الأرض ما بين الأسباط الكبيرة والصغيرة بالقرعة.","26:57":"أما اللاويون الذين أحصوا حسب عشائرهم فهم: الجرشونيون من نسل جرشون، والقهاتيون من نسل قهات، والمراريون من نسل مراري.","26:58":"ومن عشائر لاوي أيضا: عشيرة اللبنيين، وعشيرة الحبرونيين، وعشيرة المحليين، وعشيرة الموشيين، وعشيرة القورحيين. وكان عمرام منحدرا من نسل قهات.","26:59":"واسم امرأة عمرام يوكابد بنت لاوي، التي ولدت في مصر وأنجبت لعمرام هرون وموسى ومريم أختهما.","26:60":"وأنجب هرون ناداب وأبيهو وألعازار وإيثامار.","26:61":"أما ناداب وأبيهو فقد ماتا عندما قربا نارا غير مقدسة أمام الرب.","26:62":"وكان المحصون من ذكور اللاويين ثلاثة وعشرين ألفا، من ابن شهر فما فوق. هؤلاء لم يحصوا مع بقية الإسرائيليين، لأنهم لم يرثوا نصيبا بين بني إسرائيل.","26:63":"هؤلاء هم الذين أحصاهم موسى وألعازار الكاهن، حين قاما بإحصاء بني إسرائيل في سهول موآب بالقرب من نهر الأردن مقابل أريحا.","26:64":"ولم يكن بين هؤلاء المحصين إنسان ممن عدهم موسى وهرون سابقا في صحراء سيناء،","26:65":"لأن الرب كان قد قال لهم، إنهم جميعا سيموتون في الصحراء، فلم يبق منهم إنسان سوى كالب بن يفنة ويشوع بن نون.","27:1":"وأقبلت بنات صلفحاد بن حافر بن جلعاد بن ماكير بن منسى، المنتميات إلى عشائر منسى بن يوسف، وهن: محلة ونوعة وحجلة وملكة وترصة.","27:2":"ووقفن أمام موسى وألعازار الكاهن، وأمام القادة والشعب، عند مدخل خيمة الاجتماع وقلن:","27:3":"«لقد مات أبونا في الصحراء، ولم يكن من القوم الذين اجتمعوا مع قورح وتمردوا ضد الرب، بل بخطيئته مات من غير أن يعقب بنين.","27:4":"فلماذا يسقط اسم أبينا من بين عشيرته لأنه لم يخلف ابنا؟ أعطنا ملكا بين أعمامنا».","27:5":"فرفع موسى قضيتهن أمام الرب.","27:6":"فقال الرب لموسى:","27:7":"«إن بنات صلفحاد قد نطقن بحق، فأعطهن نصيبا ملكا لهن بين أعمامهن. انقل إليهن نصيب أبيهن.","27:8":"وأوص بني إسرائيل أن أي رجل يموت من غير أن يخلف ابنا، تنقلون ملكه إلى ابنته.","27:9":"وإن لم تكن له ابنة تعطون ملكه لإخوته.","27:10":"وإن لم يكن له إخوة، فأعطوا ملكه لأعمامه.","27:11":"وإن لم يكن له أعمام، فأعطوا ملكه لأقرب أقربائه من عشيرته، فيرثه. ولتكن هذه فريضة قضاء لبني إسرائيل كما أمر الرب موسى».","27:12":"وقال الرب لموسى: «اصعد إلى جبل عباريم، وانظر من عبر النهر إلى الأرض التي أعطيتها لبني إسرائيل.","27:13":"ومتى شاهدتها تموت وتنضم إلى قومك أيضا، نظير أخيك هرون.","27:14":"لأنكما في صحراء صين عصيتما قولي، حين تمرد الشعب، ولم تقدساني أمام أعينهم، إذ لم تأمرا الماء بالتفجر من الصخرة». ذلك ماء مريبة عند قادش في صحراء صين","27:15":"فقال موسى للرب:","27:16":"«ليقم الرب، إله أرواح جميع الناس، قائدا للشعب،","27:17":"يخرج ويدخل أمامهم، يقودهم ويرجعهم لئلا تصبح جماعة الرب كغنم لا راعي لها».","27:18":"فقال الرب لموسى: «خذ يشوع بن نون، رجلا فيه روح الرب، وضع يدك عليه.","27:19":"ثم أوقفه أمام ألعازار وأمام الجماعة كلها، وأوصه بحضرتهم،","27:20":"وسلمه بعض سلطتك، لكي يطيعه كل جماعة بني إسرائيل.","27:21":"ليمثل أمام ألعازار الكاهن الذي يتلقى القرارات بشأنه بواسطة الأوريم أمام الرب. فلا يخرجون ولا يدخلون إلا بأمره، هو وجميع الشعب معه».","27:22":"فأخذ موسى يشوع وأوقفه أمام ألعازار الكاهن وسائر الجماعة،","27:23":"ووضع يديه عليه وأوصاه كما أمره الرب.","28:1":"وقال الرب لموسى:","28:2":"«أوص بني إسرائيل وقل لهم: عليكم أن تقربوا لي طعام وقائدي في مواعيده كرائحة رضى لي،","28:3":"وقل لهم: هذا هو الوقود الذي تقدمونه للرب: حملان حوليان صحيحان، يوميا ليكونا محرقة دائمة.","28:4":"قدموا أحد الحملين صباحا، والحمل الآخر ما بين العشاءين،","28:5":"مع تقدمة من عشر الإيفة (نحو لترين ونصف اللتر) من دقيق معجون بربع الهين (نحو لتر) من زيت زيتون مرضوض.","28:6":"هذه هي التقدمة المعتادة التي نص عليها في جبل سيناء لتكون رائحة رضى ومحرقة دائمة للرب.","28:7":"ويسكب مع الحمل الواحد ربع الهين (نحو لتر) من الخمر للرب في القدس.","28:8":"أما الحمل الثاني فتقدمونه بين العشاءين كتقدمة الصباح، مع سكيبه، فيكون محرقة رائحة رضى للرب.","28:9":"وفي يوم السبت تقربون حملين حوليين صحيحين، مع تقدمة من عشرين (نحو خمسة لترات) من دقيق معجون بزيت، وأيضا سكيب خمر.","28:10":"فتكون هذه محرقة في كل سبت، علاوة على المحرقة الدائمة وسكيبها.","28:11":"وتقربون أيضا في اليوم الأول من كل شهر محرقة للرب من ثورين وكبش واحد، وسبعة حملان حولية صحيحة.","28:12":"وتقدمة من ثلاثة أعشار (نحو سبعة لترات ونصف اللتر) من دقيق معجون بزيت، لكل ثور، وتقدمة من عشرين (نحو خمسة لترات) من دقيق معجون بزيت للكبش الواحد.","28:13":"وتقدمة من عشر واحد (نحو لتر ين ونصف اللتر) من دقيق معجون بزيت لكل حمل، فتكون محرقة رائحة رضى وقربانا للرب.","28:14":"وتكون سكائب خمرها نصف الهين (نحو لترين) للثور، وثلث الهين (نحو لتر وثلث اللتر) للكبش، وربع الهين (نحو لتر) للحمل. هذه محرقة تقرب كل شهر من أشهر السنة.","28:15":"كذلك تقدمون تيسا واحدا من المعز ذبيحة خطيئة للرب علاوة على المحرقة الدائمة المقربة مع سكيبها من الخمر.","28:16":"ويكون اليوم الرابع عشر من الشهر الأول العبري (أي شهر آذار ; مارس) فصحا للرب.","28:17":"وفي اليوم الخامس عشر منه تحتفلون وتأكلون فطيرا سبعة أيام.","28:18":"وتقيمون في اليوم الأول محفلا مقدسا، تمتنعون فيه عن أي عمل.","28:19":"وتصعدون ذبائح محرقات للرب ثورين وكبشا واحدا وسبعة حملان حولية صحيحة.","28:20":"وتكون تقدمتها ثلاثة أعشار (نحو سبعة لترات ونصف اللتر) من دقيق معجون بزيت لكل ثور، وعشرين (نحو خمسة لترات) للكبش الواحد.","28:21":"وعشرا واحدا (نحو لترين ونصف) لكل حمل من السبعة الحملان.","28:22":"وتقربون أيضا تيسا واحدا ذبيحة خطيئة للتكفير عنكم،","28:23":"فتكون هذه التقدمة علاوة على محرقة الصباح الدائمة التي تصعدونها.","28:24":"هكذا تصنعون كل يوم طوال السبعة الأيام، فتقدمون طعام وقود رائحة رضى للرب، فضلا عن المحرقة الدائمة التي تقرب مع سكيب خمرها.","28:25":"ثم تقيمون محفلا مقدسا في اليوم السابع، تمتنعون فيه عن أي عمل.","28:26":"وفي يوم أول الأثمار حين تقربون تقدمة جديدة للرب في أثناء عيد الأسابيع، أقيموا محفلا مقدسا، تمتنعون فيه عن أي عمل.","28:27":"وتقربون محرقة كرائحة رضى للرب، من ثورين وكبش واحد وسبعة حملان حولية.","28:28":"أما تقدمتهن فتكون ثلاثة أعشار (نحو سبعة لترات ونصف اللتر) من دقيق معجون بزيت لكل ثور، وعشرين (نحو خمسة لترات) للكبش الواحد","28:29":"وعشرا واحدا (نحو لترين ونصف اللتر) لكل حمل من الحملان السبعة.","28:30":"وأيضا تقدمون تيسا واحدا من المعز للتكفير عنكم،","28:31":"وهكذا علاوة على المحرقة الدائمة وتقدمتها، أصعدوا هذه مع سكائبها من الخمر، على أن تكون الذبائح خالية من كل عيب.","29:1":"وفي اليوم الأول من الشهر السابع العبري (أي شهر أيلول ; سبتمبر) تقيمون لكم محفلا مقدسا للرب، تمتنعون فيه عن أي عمل، إذ يكون لكم يوم نفخ بالأبواق.","29:2":"وتصعدون فيه محرقة لرائحة رضى للرب ثورا واحدا وكبشا واحدا وسبعة حملان حولية سليمة.","29:3":"وتكون تقدمتها ثلاثة أعشار (نحو سبعة لترات ونصف اللتر) من دقيق معجون بزيت للثور، وعشرين (نحو خمسة لترات) للكبش،","29:4":"وعشرا واحدا (نحو لترين ونصف اللتر) لكل حمل من السبعة الحملان.","29:5":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة للتكفير عنكم.","29:6":"فتكون هذه علاوة على المحرقة الشهرية وتقدمتها من الدقيق والمحرقة اليومية الدائمة وتقدمتها من الدقيق، مع ما يرافقها من سكائب الخمر، هي محرقة رائحة رضى للرب.","29:7":"وفي اليوم العاشر من الشهر السابع تقيمون لكم محفلا مقدسا، تصومون فيه وتمتنعون عن أي عمل.","29:8":"وتقربون محرقة للرب رائحة رضى ثورا واحدا وكبشا واحدا وسبعة حملان حولية سليمة.","29:9":"تكون تقدمتها ثلاثة أعشار (نحو سبعة لترات ونصف اللتر) من دقيق معجون بزيت للثور، وعشرين (نحو خمسة لترات) للكبش الواحد،","29:10":"وعشرا واحدا (نحو لترين ونصف اللتر) لكل حمل من السبعة الحملان","29:11":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة للتكفير عنكم. فتكون هذه علاوة على ذبيحة الخطيئة السنوية المقدمة في يوم الكفارة، والمحرقة اليومية الدائمة مع ما يرافقها من سكائب الخمر.","29:12":"وفي اليوم الخامس عشر من الشهر نفسه تقيمون لكم محفلا مقدسا، تمتنعون فيه عن أي عمل، وتحتفلون فيه للرب سبعة أيام.","29:13":"وتقربون في اليوم الأول محرقة رائحة رضى للرب، ثلاثة عشر ثورا وكبشين وأربعة عشر حملا حوليا سليما.","29:14":"وتكون تقدمتها ثلاثة أعشار (نحو سبعة لترات ونصف اللتر) من دقيق معجون بزيت لكل ثور من الثيران الثلاثة عشر، وعشرين (نحو خمسة لترات) لكل كبش من الكبشين.","29:15":"وعشرا واحدا (نحو لترين ونصف اللتر) لكل حمل من الأربعة عشر حملا.","29:16":"كما تقدمون تيسا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة وتقدمتها وسكيبها من الخمر.","29:17":"وتقربون في اليوم الثاني اثني عشر ثورا وكبشين وأربعة عشر حملا حوليا سليما.","29:18":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثيران والكبشين والحملان، هي التقدمة المعتادة بما يتفق مع عددها.","29:19":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة، وتقدمتها من الدقيق وسكائب الخمر.","29:20":"وتقربون في اليوم الثالث أحد عشر ثورا وكبشين وأربعة عشر حملا حوليا سليما.","29:21":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثيران والكبشين والحملان هي التقدمة المعتادة بما يتفق مع عددها.","29:22":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة وتقدمتها من الدقيق وسكائب الخمر.","29:23":"وتقربون في اليوم الرابع عشرة ثيران وكبشين وأربعة عشر حملا حوليا سليما.","29:24":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثيران والكبشين والحملان هي التقدمة المعتادة بما يتفق مع عددها.","29:25":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة وتقدمتها من الدقيق وسكائب الخمر.","29:26":"وتقربون في اليوم الخامس تسعة ثيران وكبشين وأربعة عشر حملا حوليا صحيحا،","29:27":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثيران والكبشين والحملان هي التقدمة المعتادة بما يتفق مع عددها.","29:28":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة وتقدمتها من الدقيق وسكائب الخمر.","29:29":"وتقربون في اليوم السادس ثمانية ثيران وكبشين وأربعة عشر حملا حوليا سليما.","29:30":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثيران والكبشين والحملان هي التقدمة المعتادة بما يتفق مع عددها.","29:31":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة وتقدمتها من الدقيق وسكائب الخمر.","29:32":"وتقربون في اليوم السابع سبعة ثيران وكبشين وأربعة عشر حملا حوليا سليما.","29:33":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثيران والكبشين والحملان هي التقدمة المعتادة بما يتفق مع عددها.","29:34":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة، علاوة على المحرقة اليومية الدائمة وتقدمتها من الدقيق وسكائب الخمر.","29:35":"وفي اليوم الثامن تجتمعون للعبادة وفيه تمتنعون عن أي عمل.","29:36":"وتقربون محرقة لتكون رائحة رضى للرب ثورا واحدا وكبشا واحدا وسبعة حملان حولية سليمة.","29:37":"وتكون تقدمتها من الدقيق وسكائب الخمر لكل من الثور والكبش والحملان هي التقدمة المعتادة بما يتفق مع عددها.","29:38":"كما تقدمون تيسا واحدا من المعز ذبيحة خطيئة علاوة على المحرقة اليومية الدائمة وتقدمتها من الدقيق وسكائب الخمر.","29:39":"فهذه هي الذبائح التي تقربونها للرب في مواسم أعيادكم، علاوة على نذوركم وقرابين محرقاتكم الطوعية وتقدماتكم من الدقيق وسكائب خمركم وذبائح سلامتكم».","29:40":"فأبلغ موسى بني إسرائيل جميع ما أمره به الرب.","30:1":"وقال موسى لقادة أسباط بني إسرائيل: «إليكم ما أمر به الرب:","30:2":"إذا نذر رجل نذرا للرب، أو أقسم أن يلتزم بأمر ما، فعليه أن يفي بكلامه وينفذ كل ما تعهد به.","30:3":"ولكن إذا نذرت صبية نذرا للرب وألزمت نفسها بأمر، وهي ما برحت في بيت أبيها،","30:4":"وسمع أبوها ما نذرته أو تعهدت به، وسكت، فإنها تكون ملزمة بكل نذورها وتعهداتها.","30:5":"ولكن إن منعها أبوها عند سماعه ما نذرت أو تعهدت به، فإنها لا تكون ملزمة بالإيفاء، والرب يصفح عنها لأن أباها قد منعها.","30:6":"وإذا تزوجت بعد أن نذرت أو تعهدت بما ألزمت به نفسها،","30:7":"ثم عرف زوجها بنذورها فسكت عنها، تصبح ملزمة بها.","30:8":"وإن منعها زوجها عند معرفته بنذورها، فإن ما تعهدت به وألزمت نفسها به يصبح لاغيا، والرب يصفح عنها.","30:9":"وأما نذر الأرملة والمطلقة فكل ما تعهدت به يثبت عليها.","30:10":"إن نذرت امرأة متزوجة أو أقسمت أن تلتزم بأمر، وهي ما برحت في بيت زوجها،","30:11":"وسمع زوجها ولم يعترض، تصبح ملزمة بكل نذورها وبكل ما تعهدت به.","30:12":"ولكن إن أبطل زوجها نذورها عند معرفته بها، فإن كل ما تعهدت به من نذور، أو ما ألزمت به نفسها، يصبح لاغيا، لأن زوجها قد أبطل نذورها، والرب يصفح عنها.","30:13":"كل نذر وكل تعهد ملزم بقمع النفس، فزوجها يثبته، وزوجها يبطله.","30:14":"ولكن إن لم يعترض زوجها خلال يوم من معرفته به، فقد أثبت عليها كل نذورها وتعهداتها، لأنه لم يعترض عليها عند معرفته بها.","30:15":"ولكن إن أبطل نذورها بعد ذلك، فإنه يحمل عقاب ذنبها».","30:16":"هذه هي الفرائض التي أمر بها الرب موسى بشأن نذور الأنثى، الخاصة بالزوج وزوجته، والأب وابنته الصبية التي ما برحت مقيمة في بيته.","31:1":"وقال الرب لموسى:","31:2":"«انتقم من المديانيين لبني إسرائيل، وبعدها تموت وتنضم إلى قومك».","31:3":"فقال موسى للشعب: «جهزوا منكم رجالا مجندين لمحاربة المديانيين والانتقام للرب منهم.","31:4":"أرسلوا للحرب ألفا واحدا من كل سبط من أسباط إسرائيل».","31:5":"فتم اختيار ألف من كل سبط، فكانوا اثني عشر ألفا من بين ألوف إسرائيل مجردين للقتال.","31:6":"فأرسلهم موسى، ألفا من كل سبط، للحرب بقيادة فينحاس بن ألعازار الكاهن، الذي أخذ معه أمتعة القدس وأبواق الهتاف.","31:7":"فحاربوا المديانيين كما أمر الرب وقتلوا كل ذكر؛","31:8":"وقتلوا معهم ملوكهم الخمسة: أوي وراقم وصور وحور ورابع، كما قتلوا بلعام بن بعور بحد السيف.","31:9":"وأسر بنو إسرائيل نساء المديانيين وأطفالهم، وغنموا جميع بهائمهم ومواشيهم وسائر أملاكهم،","31:10":"وأحرقوا مدنهم كلها بمساكنها وحصونها،","31:11":"واستولوا على كل الغنائم والأسلاب من الناس والحيوان،","31:12":"ورجعوا إلى موسى وألعازار الكاهن وجماعة إسرائيل بالسبي والأسلاب والغنيمة إلى المخيم في سهول موآب بالقرب من نهر الأردن مقابل أريحا.","31:13":"فخرج موسى وألعازار وكل قادة إسرائيل لاستقبالهم إلى خارج المخيم،","31:14":"فأبدى موسى سخطه على قادة الجيش من رؤساء الألوف ورؤساء المئات القادمين من الحرب،","31:15":"وقال لهم: «لماذا استحييتم النساء؟","31:16":"إنهن باتباعهن نصيحة بلعام أغوين بني إسرائيل لعبادة فغور، وكن سبب خيانة للرب، فتفشى الوبأ في جماعة الرب.","31:17":"فالآن اقتلوا كل ذكر من الأطفال، واقتلوا أيضا كل امرأة ضاجعت رجلا،","31:18":"ولكن استحيوا لكم كل عذراء لم تضاجع رجلا.","31:19":"وأما أنتم فامكثوا خارج المخيم سبعة أيام، وعلى كل من قتل نفسا، ومن لمس قتيلا أن يتطهر في اليوم الثالث، وفي اليوم السابع. افعلوا هذا أنتم وسباياكم.","31:20":"وكذلك طهروا كل ثوب، وكل متاع جلدي، وكل ما هو مصنوع من شعر المعز وكل آنية من خشب».","31:21":"وقال ألعازار الكاهن للمحاربين: «هذه هي فريضة الشريعة التي أمر بها الرب موسى:","31:22":"الذهب والفضة والنحاس والحديد والقصدير والرصاص،","31:23":"وكل ما يتحمل حرارة النار، أجيزوه فيها فيصبح طاهرا. ولكن عليكم أيضا أن تطهروه بماء التطهير، وما لا يحتمل النار طهروه بماء التطهير فقط.","31:24":"ثم اغسلوا ثيابكم في اليوم السابع فتكونوا طاهرين. وبعد ذلك تدخلون المخيم».","31:25":"وقال الرب لموسى:","31:26":"«أحص أنت وألعازار الكاهن ورؤساء العشائر الغنائم والسبي من الناس والحيوان،","31:27":"وقسم الغنائم مناصفة بين الجند المشتركين في الحرب وبين كل الجماعة.","31:28":"وخذ نصيبا للرب من غنائم أهل الحرب، واحدا من كل خمس مئة من الناس والبقر والحمير والغنم.","31:29":"من نصف أهل الحرب تأخذها وتعطيها لألعازار الكاهن تقدمة للرب.","31:30":"وتأخذ من نصف بني إسرائيل واحدا من كل خمسين من الناس والبقر والحمير والغنم وسائر البهائم، وتعطيها للاويين القائمين على خدمة خيمة الاجتماع».","31:31":"فنفذ موسى وألعازار الكاهن كما أمر الرب موسى.","31:32":"وكان النهب المتبقي من غنائم رجال الحرب من الغنم ست مئة وخمسة وسبعين ألفا،","31:33":"ومن البقر اثنين وسبعين ألفا،","31:34":"ومن الحمير واحدا وستين ألفا،","31:35":"ومن العذارى اللواتي لم يضاجعن ذكرا اثنين وثلاثين ألفا.","31:36":"فكان النصف نصيب أهل الحرب، من الغنم ثلاث مئة وسبعة وثلاثين ألفا وخمس مئة.","31:37":"وكانت زكاة الرب منها ست مئة وخمسة وسبعين،","31:38":"ومن البقر ستة وثلاثين ألفا، وزكاة الرب منها اثنين وسبعين،","31:39":"ومن الحمير ثلاثين ألفا وخمس مئة، وزكاة الرب منها واحدا وستين،","31:40":"ومن النساء العذارى ستة عشر ألفا، وزكاة الرب منها اثنين وثلاثين نفسا.","31:41":"فأعطى موسى الزكاة تقدمة الرب لألعازار الكاهن، كما أمر الرب موسى.","31:42":"أما نصف غير المحاربين من الإسرائيليين من الغنيمة الذي قسمه موسى من كامل غنائم أهل الحرب،","31:43":"فكان من الغنم ثلاث مئة وسبعة وثلاثين ألفا وخمس مئة،","31:44":"ومن البقر ستة وثلاثين ألفا،","31:45":"ومن الحمير ثلاثين ألفا وخمس مئة،","31:46":"ومن العذارى ستة عشر ألفا.","31:47":"فأفرز موسى من نصيب الإسرائيليين واحدا من كل خمسين من النساء ومن البهائم وأعطاها للاويين القائمين على خدمة المسكن، كما أمر الرب موسى.","31:48":"ثم تقدم قادة الجند من رؤساء الألوف ورؤساء المئات إلى موسى،","31:49":"وقالوا له: «لقد أحصى عبيدك عدد جنودهم المحاربين، فلم يفقد منا إنسان.","31:50":"لذلك يقدم كل واحد منا قربان الرب في ما وجده من أمتعة ذهب: حجول وأساور وخواتم وأقراط وقلائد للتكفير عن أنفسنا أمام الرب».","31:51":"فأخذ موسى وألعازار الكاهن منهم كل ما هو مصنوع من الذهب،","31:52":"فكانت جملة ذهب التقدمة التي قربوها للرب ستة عشر ألفا وسبع مئة وخمسين شاقلا (نحو مئتي كيلوجراما) قدمها رؤساء الألوف ورؤساء المئات.","31:53":"أما الجند فقد أخذ كل منهم ما اغتنمه لنفسه.","31:54":"وحمل موسى وألعازار الكاهن الذهب الذي قدمه رؤساء الألوف ورؤساء المئات وأتيا به إلى خيمة الاجتماع تذكارا لبني إسرائيل أمام الرب.","32:1":"وكان لسبطي رأوبين وجاد مواش كثيرة جدا. فلما أقبلوا على أرض يعزير وأرض جلعاد وجدوا أنها صالحة لرعي المواشي.","32:2":"فقالوا لموسى وألعازار الكاهن ورؤساء الشعب:","32:3":"«إن أراضي عطاروت وديبون ويعزير ونمرة وحشبون وألعالة وشبام ونبو وبعون","32:4":"الأراضي التي أخضعها الرب لبني إسرائيل هي مراع صالحة لرعي مواشي عبيدك.","32:5":"فإن حسن لديك، أعط هذه الأراضي لعبيدك ملكا، ولا تدعنا نعبر نهر الأردن».","32:6":"فقال موسى لأبناء سبطي جاد ورأوبين: «أينطلق إخوتكم لخوض الحرب وأنتم هنا قاعدون؟","32:7":"لماذا تضعفون قلوب الإسرائيليين عن العبور إلى الأرض التي وهبها الرب لهم؟","32:8":"إن هذا ما فعله آباؤكم حين أرسلتهم من قادش برنيع ليتجسسوا الأرض،","32:9":"فبعد أن بلغوا وادي أشكول وتجسسوا الأرض أضعفوا قلوب الإسرائيليين عن العبور إلى الأرض التي وهبها الرب لهم.","32:10":"فاحتدم في ذلك اليوم غضب الرب وقال:","32:11":"لأنهم لم يطيعوني من كل قلوبهم فإن الرجال من ابن عشرين سنة فما فوق من الذين خرجوا من مصر لن يروا الأرض التي أقسمت أن أهبها لنسل إبراهيم وإسحق ويعقوب،","32:12":"ما عدا كالب بن يفنة القنزي ويشوع بن نون، لأنهما أطاعاني من كل قلبيهما.","32:13":"وإذ اشتد غضب الرب على بني إسرائيل أتاههم في الصحراء أربعين سنة، حتى تم فناء كل الجيل الذي ارتكب الشر في عيني الرب.","32:14":"وها أنتم نتاج تربية قوم خطاة، ترتكبون وزر آبائكم، لتزيدوا من شدة غضبه على إسرائيل.","32:15":"لأنكم إن تخليتم عن طاعته، يعود ويتركهم في الصحراء وتكونون أنتم سبب هلاكهم».","32:16":"فاقتربوا منه وقالوا: «سنبني حظائر لمواشينا ومدنا لأطفالنا ونسائنا،","32:17":"أما نحن فنتسلح وننطلق مسرعين أمام بني إسرائيل حتى يبلغوا أماكنهم بينما يمكث نساؤنا وأطفالنا في مدن محصنة تقيهم هجمات أهل الأرض،","32:18":"ولا نرجع إلى بيوتنا حتى يمتلك كل واحد من بني إسرائيل نصيبه من الميراث.","32:19":"وإننا لا نرث معهم شيئا في غربي نهر الأردن، لأننا قد حصلنا على نصيبنا في الأراضي الواقعة في شرقيه».","32:20":"فقال لهم موسى: «إن وفيتم بعهدكم فحملتم السلاح لخوض الحرب أمام الرب،","32:21":"وعبر كل متسلح منكم نهر الأردن ليحارب أمام الرب حتى يتم طرد أعدائه من أمامه،","32:22":"فتخضع الأرض بين يدي الرب، وبعدها ترجعون، عندئذ تكونون أبرياء عند الرب وعند شعب إسرائيل، وتصبح هذه الأرض ملكا لكم أمام الرب.","32:23":"ولكن إن نكثتم بتعهدكم فإنكم تخطئون إلى الرب. وثقوا أن خطيئتكم ستلاحقكم.","32:24":"ابنوا مدنا لنسائكم وأطفالكم، وحظائر لغنمكم، ونفذوا ما تعهدتم به».","32:25":"فأجاب أبناء سبطي جاد ورأوبين موسى: «سيفعل عبيدك كأمر سيدهم،","32:26":"إذ يمكث أطفالنا ونساؤنا ومواشينا وكل بهائمنا في مدن جلعاد،","32:27":"بينما يعبر كل منخرط في الجيش من عبيدك نهر الأردن للحرب أمام الرب كما أمر سيدنا».","32:28":"فأوصى بهم موسى ألعازار الكاهن ويشوع بن نون ورؤساء أسباط إسرائيل","32:29":"قائلا: «إن عبر معكم نهر الأردن كل متجرد للحرب بين يدي الرب من أبناء سبطي جاد ورأوبين، وتم الاستيلاء على الأرض، تورثونهم أرض جلعاد ملكا.","32:30":"ولكن إن تقاعسوا عن العبور لخوض الحرب معكم، فإنكم تورثونهم في وسطكم في أرض كنعان».","32:31":"فأجاب أبناء سبطي جاد ورأوبين: «كل ما تكلم الرب به من نحو عبيدك نلتزم به،","32:32":"فإننا نعبر بكامل أسلحتنا لنحارب بين يدي الرب في أرض كنعان، ولكننا لا نرث نصيبا في غربي الأردن».","32:33":"فوهب موسى أبناء سبطي جاد ورأوبين وأبناء نصف سبط منسى بن يوسف مملكة سيحون ملك الأموريين، ومملكة عوج ملك باشان بما فيهما من أراض ومدن واقعة ضمن حدودهما.","32:34":"فرمم أبناء سبط جاد مدن ديبون وعطاروت وعروعير،","32:35":"وعطروت شوفان ويعزير ويجبهة،","32:36":"وبيت نمرة وبيت هاران، وجعلوها مدنا محصنة وبنوا أيضا حظائر لغنمهم.","32:37":"وبنى أبناء رأوبين مدن حشبون وألعالة وقريتايم،","32:38":"ونبو وبعل معون اللتين تم تغيير اسميهما، وسبمة وأطلقوا أسماء أخرى على المدن التي بنوها.","32:39":"وتوجه أبناء ماكير من سبط منسى نحو جلعاد واستولوا عليها، وطردوا الأموريين منها،","32:40":"فوهب موسى جلعاد لنسل ماكير بن منسى فأقاموا فيها.","32:41":"واستولى يائير من سبط منسى على مزارع جلعاد، ودعاها حووث يائير (ومعناها قرى يائير).","32:42":"كما انطلق نوبح وتملك قناة والقرى المحيطة بها وأطلق عليها اسمه «نوبح».","33:1":"هذا هو سجل رحلات بني إسرائيل منذ خروجهم من ديار مصر، بقيادة موسى وهرون.","33:2":"فقد دون موسى مراحل رحلاتهم، تلبية لأمر الرب، حسب وقوعها.","33:3":"في اليوم الخامس عشر من الشهر الأول (العبري)، في صباح غد الفصح، ارتحل الإسرائيليون من رعمسيس بقوة أمام أعين جميع المصريين،","33:4":"الذين كانوا يدفنون أبكارهم الذين أهلكهم الرب، وبعد أن أنزل قضاءه بآلهتهم.","33:5":"وتوجه بنو إسرائيل من رعمسيس وخيموا في سكوت.","33:6":"ثم ارتحلوا من سكوت وحلوا في إيثام المجاورة لطرف الصحراء.","33:7":"ثم ارتدوا من إيثام إلى فم الحيروث مقابل بعل صفون، ونزلوا أمام مجدل.","33:8":"بعد ذلك انطلقوا من أمام الحيروث واجتازوا في وسط البحر إلى الصحراء، وتقدموا مسيرة ثلاثة أيام في صحراء إيثام، وأقاموا في مارة.","33:9":"ثم ارتحلوا من مارة وأقبلوا على إيليم، حيث وجدوا فيها اثنتي عشرة عين ماء وسبعين نخلة، فخيموا هناك.","33:10":"وما لبثوا أن مضوا من إيليم ونزلوا عند البحر الأحمر.","33:11":"وانطلقوا من جوار البحر الأحمر وحطوا رحالهم في صحراء سين.","33:12":"ثم توجهوا من صحراء سين وأقاموا في دفقة.","33:13":"وانتقلوا من دفقة ونزلوا في ألوش.","33:14":"وتقدموا من ألوش ونصبوا خيامهم في رفيديم. ولم يجد الشعب هناك ماء ليشرب.","33:15":"ثم مضوا من رفيديم وأقاموا في صحراء سيناء.","33:16":"وانطلقوا من صحراء سيناء وخيموا في قبروت هتأوة.","33:17":"وغادروا قبروت هتأوة ونزلوا في حضيروت","33:18":"وانتقلوا من حضيروت وحطوا رحالهم في رثمة.","33:19":"ثم ارتحلوا من رثمة وتوقفوا في رمون فارص.","33:20":"ومضوا من رمون فارص وخيموا في لبنة.","33:21":"وتقدموا من لبنة وأقاموا في رسة.","33:22":"ثم انطلقوا من رسة ونصبوا خيامهم في قهيلاتة.","33:23":"وتوجهوا من قهيلاتة ونزلوا في جبل شافر.","33:24":"وانتقلوا من جبل شافر وحطوا رحالهم في حرادة.","33:25":"ثم ارتحلوا من حرادة وتوقفوا في مقهيلوت.","33:26":"وسافروا من مقهيلوت وخيموا في تاحت.","33:27":"ومضوا من تاحت وأقاموا في تارح.","33:28":"وانطلقوا من تارح ونزلوا في مثقة.","33:29":"وتوجهوا من مثقة ونصبوا خيامهم في حشمونة.","33:30":"ثم انتقلوا من حشمونة وتوقفوا في مسيروت.","33:31":"وتقدموا من مسيروت وحطوا رحالهم في بني يعقان.","33:32":"وغادروا بني يعقان وخيموا في حور الجدجاد.","33:33":"وسافروا من حور الجدجاد وأقاموا في يطبات.","33:34":"ومضوا من يطبات ونزلوا في عبرونة.","33:35":"وانطلقوا من عبرونة ونصبوا خيامهم في عصيون جابر.","33:36":"ثم توجهوا من عصيون جابر وتوقفوا في صحراء صين، وهي قادش.","33:37":"وانتقلوا من قادش وحطوا رحالهم في جبل هور في طرف أرض أدوم.","33:38":"وفي اليوم الأول من الشهر الخامس (أي شهر تموز ; يوليو) من السنة الأربعين لخروج بني إسرائيل من ديار مصر، صعد هرون الكاهن إلى جبل هور حسب أمر الرب ومات هناك.","33:39":"وكان عمر هرون حين مات في جبل هور مئة وثلاثا وعشرين سنة.","33:40":"وسمع آنئذ ملك عراد الكنعاني المقيم في جنوبي أرض كنعان، بزحف الإسرائيليين.","33:41":"ثم تقدم الإسرائيليون من جبل هور وعسكروا في صلمونة.","33:42":"وغادروا صلمونة وخيموا في فونون.","33:43":"وسافروا من فونون وأقاموا في أوبوت،","33:44":"وارتحلوا من أوبوت ونزلوا في عيي عباريم على حدود موآب.","33:45":"وانطلقوا من عييم ونصبوا خيامهم في ديبون جاد.","33:46":"ثم توجهوا من ديبون جاد وتوقفوا في علمون دبلاتايم.","33:47":"وانتقلوا من علمون دبلاتايم وحطوا رحالهم في جبال عباريم مقابل نبو،","33:48":"ثم ارتحلوا من جبال عباريم ونزلوا في سهول موآب بالقرب من نهر الأردن مقابل أريحا.","33:49":"ونصبوا خيامهم في سهول موآب على محاذاة نهر الأردن، من بيت يشيموت إلى أبل شطيم.","33:50":"وقال الرب لموسى في سهول موآب بالقرب من نهر الأردن مقابل أريحا:","33:51":"«أوص بني إسرائيل وقل لهم: إنكم لابد عابرون نهر الأردن نحو أرض كنعان،","33:52":"فاطردوا جميع أهل الأرض من أمامكم، ودمروا تماثيلهم المنحوتة، وأبيدوا أصنامهم المسبوكة، واهدموا كل مرتفعاتهم.","33:53":"واملكوا الأرض واستوطنوا فيها، لأنني قد وهبتكم الأرض لكي ترثوها.","33:54":"اقتسموا الأرض بالقرعة حسب أسباطكم، فالسبط الكبير يأخذ نصيبا أكبر، والسبط الصغير ينال نصيبا أقل. وكل يقيم حيث يخرج له بالقرعة، واقتسموا الأرض حسب أسباطكم.","33:55":"ولكن إن لم تطردوا أهل الأرض من أمامكم، يصبح الباقون منهم أشواكا في عيونكم، ومناخس في جوانبكم، ويضايقونكم في الأرض التي أنتم مقيمون فيها،","33:56":"عندئذ أنزل بكم ما أنا مزمع أن أنزله بهم».","34:1":"وقال الرب لموسى:","34:2":"«أوص بني إسرائيل وقل لهم: إنكم داخلون إلى أرض كنعان، وهذه هي حدود الأرض التي تكون نصيبا لكم:","34:3":"تشكل صحراء صين المتاخمة لبلاد آدوم الجزء الجنوبي من الأرض، وتبدأ الحدود الجنوبية من طرف البحر الميت إلى الشرق.","34:4":"وتمتد نحو عقبة العقارب، مرورا بصحراء صين حتى تبلغ قادش برنيع جنوبا، ثم تتجه نحو حصر أدار عبورا إلى عصمون.","34:5":"ثم تلتف الحدود من عصمون إلى وادي العريش، حيث تنتهي عند البحر الأبيض المتوسط.","34:6":"أما الحدود الغربية فتكون بمحاذاة سواحل البحر الأبيض المتوسط.","34:7":"وتبدأ الحدود الشمالية من البحر الأبيض المتوسط وتمتد شرقا حتى جبل هور،","34:8":"ومن جبل هور إلى مدخل حماة، ثم تتجه نحو صدد،","34:9":"فزفرون وتنتهي عند حصر عينان. هذا يكون لكم الحد الشمالي.","34:10":"أما الحدود الشرقية فتمتد من حصر عينان جنوبا إلى شفام.","34:11":"ثم تنحدر من شفام إلى ربلة شرقي عين، وتستمر حتى تصل إلى المنحدرات الواقعة شرقي بحر الجليل.","34:12":"ثم تتجه نحو نهر الأردن، حتى تنتهي عند البحر الميت. هذه هي أرضكم التي تشتمل عليها حدودكم من جهاتها الأربع».","34:13":"وأوصى موسى بني إسرائيل قائلا: «هذه هي الأرض التي تقتسمونها بالقرعة، التي أمر الرب أن توزع على التسعة الأسباط ونصف السبط.","34:14":"لأن سبطي رأوبين وجاد ونصف سبط منسى قد حصلوا على نصيبهم حسب عدد عائلاتهم،","34:15":"من الأراضي الواقعة في شرقي نهر الأردن مقابل أريحا».","34:16":"وقال الرب لموسى:","34:17":"«إليك اسمي الرجلين اللذين يتوليان تقسيم الأرض: ألعازار الكاهن ويشوع بن نون","34:18":"فضلا عن رئيس واحد يمثل كل سبط.","34:19":"وهذه أسماء رؤساء الأسباط: كالب بن يفنة عن سبط يهوذا.","34:20":"شموئيل بن عميهود عن سبط شمعون.","34:21":"أليداد بن كسلون عن سبط بنيامين.","34:22":"الرئيس بقي بن يجلي عن سبط دان.","34:23":"الرئيس حنيئيل بن إيفود عن سبط منسى من بني يوسف.","34:24":"الرئيس قموئيل بن شفطان عن سبط أفرايم من بني يوسف.","34:25":"الرئيس أليصافان بن فرناخ عن سبط زبولون.","34:26":"الرئيس فلطيئيل بن عزان عن سبط يساكر.","34:27":"الرئيس أخيهود بن شلومي عن سبط أشير.","34:28":"الرئيس فدهئيل بن عميهود عن سبط نفتالي».","34:29":"هؤلاء هم الرجال الذين عينهم الرب ليتولوا تقسيم أرض كنعان على بني إسرائيل.","35:1":"ثم قال الرب لموسى في سهول موآب بالقرب من نهر الأردن مقابل أريحا","35:2":"«أوص بني إسرائيل أن يعطوا اللاويين مما يرثون مدنا يسكنونها، وما حولها من مراع","35:3":"فتكون المدن لإقامتهم فيها، وأراضيها المحيطة مراعي لبهائمهم ومواشيهم وسائر حيواناتهم.","35:4":"وتمتد أرض المراعي التي تعطونها للاويين من سور المدينة إلى الخارج، ألف ذراع (نحو خمس مئة متر) في كل اتجاه.","35:5":"فقيسوا من خارج المدينة في الجانب الشرقي ألفي ذراع (نحو ألف متر). وفي الجانب الجنوبي ألفي ذراع (نحو ألف متر). وفي الجانب الغربي ألفي ذراع (نحو ألف متر)، وفي الجانب الشمالي ألفي ذراع (نحو ألف متر)، وتكون المدينة في الوسط.","35:6":"وتعطون اللاويين ست مدن للملجإ يهرب إليها القاتل، وأيضا اثنتين وأربعين مدينة.","35:7":"وهكذا تكون جملة المدن التي تعطونها للاويين ثماني وأربعين مدينة مع مراعيها.","35:8":"والمدن التي تعطونها للاويين مما يملكه الإسرائيليون، تعطونها بما يتناسب مع ميراث كل سبط: خذوا مدنا أكثر من السبط الذي يملك عددا أكبر، وخذوا مدنا أقل من السبط الذي يملك القليل، فيعطي كل سبط من مدنه بما يتناسب مع ميراثه».","35:9":"وقال الرب لموسى:","35:10":"«أوص بني إسرائيل وقل لهم: إنكم لابد عابرون نهر الأردن إلى أرض كنعان،","35:11":"فعينوا لأنفسكم مدنا تكون ملجأ لكم يلوذ بها من يقتل أحدا عن غير عمد،","35:12":"فتكون لكم المدن ملجأ يلوذ بها القاتل من ولي القتيل، لئلا يموت قبل أن يمثل أمام القضاء.","35:13":"أما المدن التي تعينونها لتكون لكم ملاجيء فهي ست مدن:","35:14":"ثلاث منها في شرقي نهر الأردن، وثلاث أخرى في أرض كنعان، وجميعها تكون مدن ملجإ،","35:15":"يلوذ بها كل من قتل نفسا عن غير عمد، سواء كان القاتل من بني إسرائيل أم من الغرباء أو المستوطنين في وسطهم. فتكون هذه المدن الست للملجإ.","35:16":"إن ضرب أحد إنسانا بأداة حديدية ومات المضروب فهو قاتل، والقاتل يقتل.","35:17":"وإن ضربه بحجر في يده أدى إلى موته فهو قاتل، والقاتل يقتل.","35:18":"أو ضربه بقطعة خشب قاتلة فهو قاتل، والقاتل يقتل.","35:19":"ومن حق ولي الدم أن يقتل القاتل إذا صادفه.","35:20":"إن دفع أحد شخصا من فرط كراهيته له أو ألقى عليه شيئا عمدا أفضى إلى موته،","35:21":"أو ضربه بيده بفعل عداوته له فمات، فالضارب يقتل لأنه قاتل. ومن حق ولي الدم أن يقتل القاتل إذا صادفه.","35:22":"ولكن إن دفع أحد شخصا، لا يكن له عداوة، أو ألقى عليه أداة ما من غير عمد،","35:23":"أو أسقط عليه حجرا قاتلا من غير أن يراه، فمات، ولم يكن يضمر له عداوة أو يسعى إلى أذيته،","35:24":"يفصل آنئذ القضاء بين القاتل وطالب الثأر، بمقتضى هذه الأحكام.","35:25":"وتنقذ الجماعة القاتل من يد ولي الدم، وترده إلى مدينة الملجإ التي لاذ بها، فيقيم فيها إلى أن يموت رئيس الكهنة الممسوح بالدهن المقدس.","35:26":"ولكن إن تخطى القاتل حدود مدينة ملجئه التي لاذ بها،","35:27":"والتقاه ولي الدم خارج حدود مدينة ملجئه وقتله، فلا يطالب بدمه.","35:28":"لأ ن عليه أن يظل مقيما في مدينة ملجئه إلى أن يموت رئيس الكهنة، وبعدها يرجع القاتل إلى أرض ميراثه.","35:29":"فتكون لكم هذه فريضة قضاء، جيلا بعد جيل، حيث تقيمون.","35:30":"كل من يقتل نفسا يحكم عليه بالموت بشهادة شهود، ولكن لا يحكم على أحد بالموت بشهادة شاهد واحد فقط.","35:31":"لا تقبلوا فدية عن نفس القاتل الذي وجب عليه الحكم بالموت، بل يجب أن يقتل.","35:32":"ولا تقبلوا فدية من القاتل غير المتعمد الذي لاذ بمدينة ملجئه ليرجع للإقامة في أرضه قبل وفاة رئيس الكهنة.","35:33":"لا تدنسوا الأرض التي أنتم فيها، لأن سفك الدم يدنس الأرض، ولا يكفر عن الأرض التي سفك عليها الدم إلا بدم السافك.","35:34":"لا تنجسوا الأرض التي أنتم مقيمون فيها وحيث أنا ساكن في وسطها، لأني أنا الرب ساكن بين بني إسرائيل».","36:1":"وتقدم رؤساء عشيرة جلعاد بن ماكير بن منسى من عشائر سبط يوسف وقالوا لموسى وقادة أسباط إسرائيل:","36:2":"«أمر الرب سيدي أن توزع الأرض بالقرعة بين بني إسرائيل. كما أمره الرب أن يعطي نصيب صلفحاد أخينا لبناته.","36:3":"فإذا تزوجن من غير سبطنا فإن نصيبهن يؤخذ من ميراث آبائنا، ويضاف إلى نصيب السبط الذي تزوجن منه، فينقص ميراثنا.","36:4":"ومتى حل يوبيل بني إسرائيل فإن الميراث يضاف إلى نصيب السبط الذي تزوجن منه، وبالتالي يؤخذ نصيبهن من ميراث سبطنا».","36:5":"فأوصى موسى بني إسرائيل بمقتضى أمر الرب قائلا: «بحق نطق رؤساء سبط بني يوسف.","36:6":"وهذا ما أمر به الرب بشأن بنات صلفحاد: ليتزوجن من حسن في أعينهن، بشرط أن يكون من سبط آبائهن،","36:7":"فلا يتحول ميراث بني إسرائيل من سبط إلى آخر، بل يظل كل سبط محتفظا بميراث آبائه.","36:8":"فكل فتاة ورثت نصيبا من سبطها، تتزوج واحدا من أبناء عشيرة سبط أبيها، لكي يرث كل واحد من بني إسرائيل نصيب آبائه.","36:9":"فلا ينتقل ميراث سبط إلى سبط آخر، بل يظل كل سبط محتفظا بميراثه».","36:10":"ففعلت بنات صلفحاد كما أمر الرب موسى.","36:11":"فتزوجت كل من محلة وترصة وحجلة وملكة ونوعة بنات صلفحاد من أبناء عمومتهن،","36:12":"وهكذا تزوجن رجالا من عشائر نسل منسى بن يوسف فبقي نصيبهن في عشيرة أبيهن وسبطه.","36:13":"هذه هي الوصايا والشرائع التي أوصى بها الرب بني إسرائيل على لسان موسى، في سهول موآب بجوار نهر الأردن مقابل أريحا."};
